/* Nxeon creator promo: shared helpers and components.
   Everything here is deterministic: no clocks, no Math.random, measurements come from a canvas
   after fonts are loaded, and every tween lives on the one paused master timeline. */
(function () {
  var NX = window.NX;

  /* ---------- text ---------- */
  NX.esc = function (s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  };
  NX.fmt = function (str, vars) {
    return String(str).replace(/\{(\w+)\}/g, function (m, k) { return vars[k] == null ? "" : vars[k]; });
  };
  /* raw string for a key, formatted, with [ ] markers left in */
  NX.raw = function (key) {
    var s = NX.S[key] != null ? NX.S[key] : NX.STRINGS.en[key];
    return NX.fmt(s, NX.ctx);
  };
  /* plain text (markers stripped) */
  NX.txt = function (key) { return NX.raw(key).replace(/[\[\]]/g, ""); };
  /* HTML with highlight markers → <em> */
  NX.hl = function (key) { return NX.esc(NX.raw(key)).replace(/\[([^\]]+)\]/g, "<em>$1</em>"); };

  /* word-split HTML for kinetic reveals: each word in a mask */
  NX.words = function (key) {
    var raw = NX.raw(key), out = [], hl = false, buf = "";
    function push(word, isHl) {
      if (!word) return;
      out.push('<span class="wm"><span class="w' + (isHl ? " hl" : "") + '">' + NX.esc(word) + "</span></span>");
    }
    for (var i = 0; i < raw.length; i++) {
      var c = raw[i];
      if (c === "[") { push(buf, hl); buf = ""; hl = true; continue; }
      if (c === "]") { push(buf, hl); buf = ""; hl = false; continue; }
      if (c === " ") { push(buf, hl); buf = ""; out.push(" "); continue; }
      buf += c;
    }
    push(buf, hl);
    return out.join("");
  };

  /* ---------- measurement (canvas, fonts must be loaded first) ---------- */
  var cv = document.createElement("canvas").getContext("2d");
  NX.measure = function (text, font) { cv.font = font; return cv.measureText(text).width; };
  NX.isDeva = function (s) { return /[ऀ-ॿ]/.test(s); };
  NX.fontFor = function (s, weight, size, mono) {
    var fam = mono ? '"Geist Mono"' : '"Geist"';
    if (NX.isDeva(s)) fam = mono ? '"Geist Mono", "Noto Sans Devanagari"' : '"Geist", "Noto Sans Devanagari"';
    return weight + " " + size + "px " + fam;
  };
  /* greedy wrap line count */
  NX.lineCount = function (text, font, maxW) {
    var words = text.split(" "), lines = 1, cur = "";
    for (var i = 0; i < words.length; i++) {
      var trial = cur ? cur + " " + words[i] : words[i];
      if (NX.measure(trial, font) > maxW && cur) { lines++; cur = words[i]; } else cur = trial;
    }
    return lines;
  };
  /* largest size (step 2px) so text fits maxLines within maxW and no single word overflows */
  NX.fitSize = function (text, weight, start, min, maxW, maxLines, mono) {
    for (var s = start; s >= min; s -= 2) {
      var f = NX.fontFor(text, weight, s, mono);
      var widest = Math.max.apply(null, text.split(" ").map(function (w) { return NX.measure(w, f); }));
      if (widest <= maxW && NX.lineCount(text, f, maxW) <= maxLines) return s;
    }
    return min;
  };

  /* ---------- money ---------- */
  NX.money = function (s) {
    var m = String(s).match(/^([^\d]*)(\d+(?:[.,]\d+)?)(.*)$/);
    if (!m) return { pre: "", num: 0, post: "", dec: 2 };
    var n = m[2].replace(",", ".");
    return { pre: m[1], num: parseFloat(n), post: m[3], dec: n.indexOf(".") >= 0 ? n.split(".")[1].length : 0 };
  };
  NX.moneyStr = function (m, v) { return m.pre + v.toFixed(m.dec) + m.post; };

  /* ---------- icons ---------- */
  NX.icon = function (id, style, cls) {
    return '<svg class="ic ' + (cls || "") + '" style="' + (style || "") + '"><use href="#i-' + id + '"/></svg>';
  };
  NX.cursorSVG = '<svg viewBox="0 0 24 24" width="60" height="60"><path d="M4.5 2.5v17.2l4.6-4.3 3.3 6.6 3-1.4-3.2-6.4 6.5-.3Z" fill="#fff" stroke="#0a1030" stroke-width="1.3" stroke-linejoin="round"/></svg>';

  /* ---------- beat label ---------- */
  /* kicker + big label; big label auto-fits to maxLines inside width */
  NX.label = function (o) {
    var text = NX.txt(o.key);
    var size = NX.fitSize(text, 700, o.size || 112, 64, o.width || 740, o.lines || 3);
    return '<div class="lbl" id="' + o.id + '" style="left:' + (o.left || 96) + "px;top:" + o.top + "px;width:" + (o.width || 740) + 'px">' +
      '<div class="kick">' + NX.esc(NX.txt(o.kick)) + "</div>" +
      '<div class="big" style="font-size:' + size + 'px">' + NX.words(o.key) + "</div></div>";
  };
  NX.labelIn = function (tl, sel, t) {
    var root = typeof sel === "string" ? document.querySelector(sel) : sel;
    var kick = root.querySelector(".kick"), ws = root.querySelectorAll(".w");
    tl.fromTo(kick, { opacity: 0, x: -24 }, { opacity: 1, x: 0, duration: 0.45, ease: "power3.out" }, t);
    tl.fromTo(ws, { yPercent: 110 }, { yPercent: 0, duration: 0.6, ease: "expo.out", stagger: Math.min(0.06, 0.4 / ws.length) }, t + 0.05);
  };
  NX.labelOut = function (tl, sel, t) {
    var root = typeof sel === "string" ? document.querySelector(sel) : sel;
    tl.to(root, { opacity: 0, y: -40, duration: 0.35, ease: "power2.in" }, t);
  };

  /* ---------- panels ---------- */
  NX.panelIn = function (tl, el, t, o) {
    o = o || {};
    tl.fromTo(el, { x: o.x == null ? 420 : o.x, y: o.y || 0, rotationY: o.ry == null ? -16 : o.ry, opacity: 0, transformPerspective: 2400, transformOrigin: "0% 50%" },
      { x: 0, y: 0, rotationY: 0, opacity: 1, duration: o.dur || 0.8, ease: "expo.out" }, t);
  };
  NX.pushOut = function (tl, el, t, o) {
    o = o || {};
    tl.to(el, { x: o.x == null ? -560 : o.x, opacity: 0, duration: o.dur || 0.42, ease: "power3.in" }, t);
  };

  /* ---------- particles (deterministic) ---------- */
  NX.burst = function (tl, layer, t, o) {
    var n = o.n || 12, html = "";
    for (var i = 0; i < n; i++) html += '<i class="pt" style="left:' + o.x + "px;top:" + o.y + "px;background:" + (i % 2 ? o.c2 || o.c : o.c) + '"></i>';
    var wrap = document.createElement("div"); wrap.className = "burst"; wrap.innerHTML = html; layer.appendChild(wrap);
    var pts = wrap.querySelectorAll(".pt");
    pts.forEach(function (p, i) {
      var a = (i / n) * Math.PI * 2 + 0.3, r = (o.r || 150) * (0.75 + 0.25 * ((i * 7) % 4) / 3);
      tl.fromTo(p, { x: 0, y: 0, scale: 1, opacity: 0 },
        { x: Math.cos(a) * r, y: Math.sin(a) * r, scale: 0.3, opacity: 0, duration: 0.7, ease: "power2.out",
          keyframes: undefined }, t);
      tl.fromTo(p, { opacity: 0 }, { opacity: 1, duration: 0.05, immediateRender: false }, t);
      tl.to(p, { opacity: 0, duration: 0.35, ease: "power1.in" }, t + 0.35);
    });
  };

  /* ---------- cursor ---------- */
  /* pts: [{t, x, y, click?}] in scene-absolute seconds; cursor element is global */
  NX.cursorPath = function (tl, pts, o) {
    o = o || {};
    var cur = document.getElementById("cursor"), fx = document.getElementById("fx");
    var p0 = pts[0];
    tl.fromTo(cur, { x: p0.x + (o.enterDx || 260), y: p0.y + (o.enterDy || 180), opacity: 0 },
      { x: p0.x, y: p0.y, opacity: 1, duration: 0.45, ease: "power3.out", immediateRender: false }, p0.t);
    for (var i = 1; i < pts.length; i++) {
      var a = pts[i - 1], b = pts[i];
      if (b.x !== a.x || b.y !== a.y) {
        var mv = b.move || Math.min(0.5, Math.max(0.25, b.t - a.t - 0.05));
        tl.to(cur, { x: b.x, y: b.y, duration: mv, ease: "power2.inOut" }, b.t - mv);
      }
    }
    pts.forEach(function (p) {
      if (!p.click) return;
      tl.to(cur, { scale: 0.82, duration: 0.08, ease: "power2.in", transformOrigin: "10% 5%" }, p.t);
      tl.to(cur, { scale: 1, duration: 0.25, ease: "back.out(3)" }, p.t + 0.08);
      var r = document.createElement("div"); r.className = "rip";
      r.style.left = (p.x - 60) + "px"; r.style.top = (p.y - 60) + "px"; fx.appendChild(r);
      tl.fromTo(r, { scale: 0.2, opacity: 0.9 }, { scale: 1.6, opacity: 0, duration: 0.6, ease: "power2.out" }, p.t + 0.02);
    });
    var last = pts[pts.length - 1];
    if (o.exit != null) tl.to(cur, { opacity: 0, duration: 0.25 }, o.exit);
    return last;
  };
  NX.press = function (tl, el, t) {
    tl.to(el, { scale: 0.94, duration: 0.09, ease: "power2.in" }, t);
    tl.to(el, { scale: 1, duration: 0.45, ease: "elastic.out(1.1, 0.45)" }, t + 0.09);
  };

  /* ---------- count (money / numbers) ---------- */
  NX.countMoney = function (tl, els, from, to, t, dur) {
    var m = NX.money(from), m2 = NX.money(to), proxy = { v: m.num };
    els = [].concat(els);
    els.forEach(function (e) { e.textContent = NX.moneyStr(m, m.num); });
    tl.to(proxy, { v: m2.num, duration: dur, ease: "power2.inOut",
      onUpdate: function () { var s = NX.moneyStr(m2, proxy.v); els.forEach(function (e) { e.textContent = s; }); } }, t);
  };
  /* typewriter into an element: chars appear across [t, t+dur] */
  NX.typeText = function (tl, el, text, t, dur) {
    var proxy = { n: 0 }; el.textContent = "";
    tl.to(proxy, { n: text.length, duration: dur, ease: "none",
      onUpdate: function () { el.textContent = text.slice(0, Math.floor(proxy.n + 0.0001)); } }, t);
  };

  /* ---------- stepper (act I spine) ---------- */
  NX.STEPS = ["Service", "Game", "Server", "Region", "Payment", "Deploy"];
  NX.stepperHTML = function () {
    var h = "";
    NX.STEPS.forEach(function (s, i) {
      if (i) h += '<div class="sl"><div class="slf" id="slf' + i + '"></div></div>';
      h += '<div class="st" id="st' + i + '"><i><b class="s-pend">' + (i + 1) + '</b><b class="s-on" id="son' + i + '">' + (i + 1) +
        '</b><b class="s-done" id="sdn' + i + '">' + NX.icon("check", "width:24px;height:24px") + "</b></i>" +
        '<span class="sp">' + s + '</span><span class="so" id="slb' + i + '">' + s + "</span></div>";
    });
    return h;
  };
