    push(buf, hl);
    return out.join("");
  };

  /* ---------- measurement (canvas, fonts must be loaded first) ---------- */
  var cv = document.createElement("canvas").getContext("2d");
  NX.measure = function (text, font) { cv.font = font; return cv.measureText(text).width; };
  NX.isDeva = function (s) { return /[\u0900-\u097F]/.test(s); };
  NX.fontFor = function (s, weight, size, mono) {
    var fam = mono ? '"Geist Mono"' : '"Geist"';
    if (NX.isDeva(s)) fam = mono ? '"Geist Mono", "Noto Sans Devanagari"' : '"Geist", "Noto Sans Devanagari"';
    return weight + " " + size + "px " + fam;
