/* Nxeon creator promo: reads the composition variables, mounts every scene, and builds the
   one paused master timeline (persistent chrome + spines + each scene's own tweens). */
(function () {
  var NX = window.NX;
  NX.scenes = [];
  NX.scene = function (def) { NX.scenes.push(def); };
  NX.orient = (document.getElementById("root").getAttribute("data-height") | 0) > 1500 ? "v" : "h";

  NX.ready = function () {
    var f = document.fonts;
    return Promise.all([
      f.load('700 100px "Geist"'), f.load('500 24px "Geist Mono"'),
      f.load('700 100px "Noto Sans Devanagari"', "अ")
    ]).catch(function () {}).then(function () { return f.ready; });
  };

  function vars() {
    var v = (window.__hyperframes && window.__hyperframes.getVariables) ? window.__hyperframes.getVariables() : {};
    var lang = NX.STRINGS[v.lang] ? v.lang : "en";
    var generic = v.generic === true || v.generic === "true";
    var code = String(v.code || "YOURCODE").toUpperCase().replace(/[^A-Z0-9_-]/g, "") || "YOURCODE";
    if (generic) code = "YOURCODE";
    var gameKey = NX.GAMES[v.game] ? v.game : "minecraft";
    var num = function (x, d) { var n = parseFloat(x); return isFinite(n) ? n : d; };
    var ctx = {
      lang: lang, generic: generic, code: code, codeLower: code.toLowerCase(),
      gameKey: gameKey, game: NX.GAMES[gameKey], isMC: gameKey.indexOf("minecraft") === 0,
      handle: String(v.creatorHandle || "").replace(/^@/, ""),
      d1: num(v.discountFirst, 50), d2: num(v.discountAfter, 10),
      priceBefore: v.priceBefore || "$4.99", priceAfter: v.priceAfter || "$2.49", renewPrice: v.renewPrice || "$7.18",
      upgradePrice: v.upgradePrice || "$4.05", upgradeRenew: v.upgradeRenew || "$12.94", tier8Price: v.tier8Price || "$23.02",
      sponsored: !(v.sponsoredTag === false || v.sponsoredTag === "false")
    };
    ctx.playAddress = v.playAddress || ((generic ? "yourserver" : ctx.codeLower) + ".play.nxeon.cloud");
    ctx.url = String(v.url || (generic ? "nxeon.cloud" : "nxeon.cloud/partner/" + code)).replace(/^https?:\/\//, "").replace(/\/$/, "");
    return ctx;
  }

  NX.buildAll = function () {
    var ctx = NX.ctx = vars();
    NX.S = NX.STRINGS[ctx.lang];
    var root = document.getElementById("root");
    root.classList.add("lang-" + ctx.lang);
    root.setAttribute("lang", ctx.lang);

    /* chrome */
    var spons = document.getElementById("spons");
    spons.textContent = NX.txt("sponsored");
    if (!ctx.sponsored) document.getElementById("c-spons").style.display = "none";
    document.getElementById("cursor").innerHTML = NX.cursorSVG;
    document.getElementById("stepper").innerHTML = NX.stepperHTML();
    var lay = NX.tabsLayout();
    var tabs = document.getElementById("tabs");
    tabs.style.width = lay.total + "px";
    tabs.innerHTML = NX.tabsHTML(lay);
    NX.tabLay = lay;

    /* scenes */
    NX.scenes.forEach(function (s) {
      var el = document.getElementById(s.id);
      if (el) el.innerHTML = s.html(ctx);
    });

    var tl = gsap.timeline({ paused: true });
    var END = 37.5;

    /* ambient background drift (one shared slow motion) */
    tl.fromTo("#glowA", { x: 0, y: 0, scale: 1 }, { x: -260, y: 120, scale: 1.12, duration: END, ease: "none" }, 0);
    tl.fromTo("#glowB", { x: 0, y: 0, scale: 1 }, { x: 220, y: -160, scale: 1.1, duration: END, ease: "none" }, 0);
    tl.fromTo("#dots", { x: 0 }, { x: -34 * 6, duration: END, ease: "none" }, 0);

    /* chrome in/out */
    tl.fromTo("#spons", { opacity: 0, y: -10 }, { opacity: 1, y: 0, duration: 0.4, ease: "power2.out" }, 0.3);
    tl.fromTo("#bug", { opacity: 0, x: -20 }, { opacity: 1, x: 0, duration: 0.45, ease: "power3.out" }, 2.45);
    tl.to("#bug", { opacity: 0, duration: 0.2 }, 32.75);

    /* act I spine: deploy stepper */
    tl.fromTo("#stepper", { opacity: 0, y: -30 }, { opacity: 1, y: 0, duration: 0.5, ease: "expo.out" }, 2.45);
    NX.stepDone(tl, 0, 2.45);
    NX.stepOn(tl, 1, 2.6);
    NX.stepDone(tl, 1, 5.75);
    NX.stepDone(tl, 2, 5.95);
    NX.stepOn(tl, 3, 6.1);
    NX.stepDone(tl, 3, 9.0);
    NX.stepOn(tl, 4, 9.15);
    NX.stepDone(tl, 4, 13.75);
    NX.stepOn(tl, 5, 13.9);
    NX.stepDone(tl, 5, 17.75);
    tl.to("#stepper", { opacity: 0, y: -40, duration: 0.4, ease: "power2.in" }, 18.45);

    /* act II spine: server tab rail (docks from under the header to the top) */
    var dockX = 760 - 400, dockY = 760 - 36;
    if (NX.orient === "h") {
      tl.fromTo("#tabs", { opacity: 0, x: dockX, y: dockY + 30 }, { opacity: 1, x: dockX, y: dockY, duration: 0.5, ease: "expo.out" }, 19.7);
      tl.to("#tabs", { x: 0, y: 0, duration: 0.6, ease: "expo.inOut" }, 21.4);
    }
    tl.fromTo("#tabhl", { x: lay[0].x, width: lay[0].w, opacity: 0 }, { opacity: 1, duration: 0.3, immediateRender: false }, 19.75);
    tl.to("#tab0", { color: "#ffffff", duration: 0.3 }, 19.75);
    NX.tabTo(tl, lay, 5, 21.85, 0);
    NX.tabTo(tl, lay, 3, 24.35, 5);
    NX.tabTo(tl, lay, 0, 27.35, 3);
    NX.tabTo(tl, lay, 5, 29.85, 0);
    tl.to("#tabs", { opacity: 0, duration: 0.25 }, 32.75);

    /* act breaks: NX brand wipes (fully covered at cut_at) */
    NX.wipe(tl, document.getElementById("wipe1"), 2.35);
    NX.wipe(tl, document.getElementById("wipe2"), 32.85);

    /* scenes */
    NX.scenes.forEach(function (s) {
      var el = document.getElementById(s.id);
      if (el) s.build(tl, ctx, el);
    });
    return tl;
  };
})();

