/* 04 · Use the creator code (9.0–13.0). Recreated "Order summary" from the real checkout. */
NX.scene({
  id: "s04",
  html: function (c) {
    var E = NX.esc, T = 9.0;
    var item = c.game.name + " — " + c.game.name + " — 2 GB";
    var itemSize = NX.fitSize(item, 600, 30, 20, 470, 1);
    var chipSize = NX.fitSize(c.code, 800, 100, 44, 540, 1);
    var fieldSize = NX.fitSize(c.code, 600, 34, 22, 600, 1, false);
    var chipW = Math.ceil(NX.measure(c.code, NX.fontFor(c.code, 800, chipSize)) + 30 + 60 + 24 + 44 + 8);
    var lbl = NX.txt("l04"), lblSize = NX.fitSize(lbl, 700, 112, 60, 740, 2);
    return '' +
      '<div class="lcol" id="s04l" style="position:absolute;left:96px;top:250px;width:760px;display:flex;flex-direction:column;align-items:flex-start;gap:34px">' +
        '<div class="lbl" style="position:relative"><div class="kick">' + E(NX.txt("k04")) + '</div><div class="big" style="font-size:' + lblSize + 'px">' + NX.words("l04") + "</div></div>" +
        '<div class="chipcode" id="s04chip" style="gap:24px;padding:22px 44px 22px 30px;width:' + chipW + 'px">' +
          NX.icon("tag", "width:60px;height:60px;color:#b3a0ff") +
          '<span id="s04chipt" style="font:800 ' + chipSize + 'px/1 Geist;letter-spacing:-.01em;white-space:nowrap"></span></div>' +
        '<div id="s04offer" style="font:500 30px/1.45 Geist;color:var(--mist)"><div>' + E(NX.txt("offerA")) + "</div><div>" + E(NX.txt("offerB")) + "</div></div>" +
      "</div>" +
      '<div class="panel" id="s04p" style="left:880px;top:150px;width:840px;height:860px;padding:38px 44px;display:flex;flex-direction:column;gap:20px">' +
        '<div style="display:flex;justify-content:space-between;align-items:baseline"><span style="font:700 34px Geist">Order summary</span><span style="font:600 24px Geist;color:#8ea2ff">Edit</span></div>' +
        '<div style="display:flex;align-items:center;gap:22px">' +
          '<div style="width:84px;height:84px;border-radius:20px;background:rgba(107,76,240,.2);border:2px solid rgba(157,133,255,.4);display:grid;place-items:center;color:#c9b8ff">' + NX.icon("game", "width:50px;height:50px") + "</div>" +
          '<div style="flex:1;min-width:0"><div style="font:600 ' + itemSize + 'px/1.2 Geist;white-space:nowrap">' + E(item) + '</div><div class="mono" style="font-size:24px;line-height:1.4;color:var(--sky);white-space:nowrap">' + E(c.playAddress) + "</div></div>" +
          '<div style="font:600 28px Geist">' + E(c.renewPrice) + "/mo</div>" +
        "</div>" +
        '<div style="display:flex;gap:30px;font:500 26px Geist;color:var(--mist)">' +
          '<span style="display:flex;align-items:center;gap:10px">' + NX.icon("cpu", "color:var(--icon-blue)") + "2 vCPU</span>" +
          '<span style="display:flex;align-items:center;gap:10px">' + NX.icon("memory", "color:var(--icon-blue)") + "2 GB RAM</span>" +
          '<span style="display:flex;align-items:center;gap:10px">' + NX.icon("storage", "color:var(--icon-blue)") + "20 GB NVMe</span>" +
        "</div>" +
        '<div style="display:flex;align-items:center;gap:14px;font:500 26px Geist"><img class="flag" src="assets/flags/ca.svg" style="width:36px;height:36px"/>Beauharnois, CA</div>' +
        '<div class="hr"></div>' +
        '<div id="s04field" style="display:flex;align-items:center;gap:18px;height:84px;padding:0 26px;border-radius:16px;border:3px solid rgba(148,163,255,.28);background:rgba(8,12,34,.9)">' +
          NX.icon("tag", "width:34px;height:34px;color:var(--mist)") +
          '<span id="s04typed" style="font:600 ' + fieldSize + 'px Geist;letter-spacing:.06em;white-space:nowrap"></span><span id="s04caret" style="display:block;width:3px;height:40px;background:#b3a0ff;margin-left:-14px"></span>' +
        "</div>" +
        '<div id="s04ap1" style="display:flex;align-items:center;gap:12px;font:500 25px Geist;color:var(--success)">' + NX.icon("check", "width:30px;height:30px") + "Creator code applied — linked to Creator Program.</div>" +
        '<div id="s04ap2" style="display:flex;align-items:center;gap:12px;font:500 25px Geist;color:#b49bff;margin-top:-8px">' + NX.icon("diamond", "width:30px;height:30px") + "Partner discount — " + E(c.d1) + "% off your first purchase</div>" +
        '<div class="hr"></div>' +
        '<div style="display:flex;justify-content:space-between;align-items:center;font:500 28px Geist;color:var(--mist)"><span>Subtotal</span>' +
          '<span style="display:flex;align-items:center;gap:16px"><span style="position:relative;display:inline-block"><span id="s04old" style="color:var(--mist)">' + E(c.priceBefore) + '</span><i id="s04strike" style="position:absolute;left:-4px;right:-4px;top:52%;height:4px;border-radius:2px;background:var(--danger);transform-origin:0 50%;transform:scaleX(0)"></i></span>' +
          '<b id="s04new" style="color:var(--ink);opacity:0">' + E(c.priceAfter) + "</b></span></div>" +
        '<div style="display:flex;justify-content:space-between;align-items:flex-end"><span style="font:700 36px Geist;padding-bottom:12px">Left to pay</span><span id="s04big" style="display:inline-block;font:700 96px/1 Geist;color:var(--sky);transform-origin:100% 80%">' + E(c.priceBefore) + "</span></div>" +
      "</div>" +
      '<div id="s04badge" style="position:absolute;left:1714px;top:612px;width:190px;height:190px;clip-path:polygon(50% 0,61% 12%,76% 6%,80% 21%,96% 24%,91% 39%,100% 50%,91% 61%,96% 76%,80% 79%,76% 94%,61% 88%,50% 100%,39% 88%,24% 94%,20% 79%,4% 76%,9% 61%,0 50%,9% 39%,4% 24%,20% 21%,24% 6%,39% 12%);background:radial-gradient(circle at 40% 35%,#a98bff,#6b3bdb 70%);display:grid;place-items:center">' +
        '<span style="font:800 56px/1 Geist;color:#fff;letter-spacing:-.03em">−' + E(c.d1) + "%</span></div>";
  },
  build: function (tl, c, el) {
    var T = 9.0, q = function (s) { return el.querySelector(s); };
    var panel = q("#s04p"), chip = q("#s04chip"), field = q("#s04field"), caret = q("#s04caret");

    NX.panelIn(tl, panel, T - 0.32);
    NX.labelIn(tl, el.querySelector(".lbl"), T - 0.05);
    tl.fromTo(chip, { opacity: 0, scale: 0.7, transformOrigin: "0% 50%" }, { opacity: 1, scale: 1, duration: 0.55, ease: "back.out(2)" }, T + 0.2);
    tl.fromTo(q("#s04offer").children, { opacity: 0, y: 18 }, { opacity: 1, y: 0, duration: 0.45, ease: "power3.out", stagger: 0.12 }, T + 2.55);

    /* field focus, typing (field + chip in sync), caret blink */
    tl.to(field, { borderColor: "#9d85ff", boxShadow: "0 0 30px rgba(139,92,246,.4)", duration: 0.3 }, T + 0.3);
    var n = c.code.length, typeDur = Math.min(1.0, 0.075 * n + 0.15);
    NX.typeText(tl, q("#s04typed"), c.code, T + 0.45, typeDur);
    NX.typeText(tl, q("#s04chipt"), c.code, T + 0.45, typeDur);
    tl.fromTo(caret, { opacity: 1 }, { opacity: 0, duration: 0.22, ease: "steps(1)", repeat: 5, yoyo: true }, T + 0.3);
    tl.to(caret, { opacity: 0, duration: 0.1 }, T + 1.55);

    /* applied */
    tl.fromTo([q("#s04ap1"), q("#s04ap2")], { opacity: 0, y: 14 }, { opacity: 1, y: 0, duration: 0.4, ease: "power3.out", stagger: 0.15 }, T + 1.55);
    tl.to(field, { borderColor: "#71cd94", boxShadow: "0 0 30px rgba(113,205,148,.35)", duration: 0.3 }, T + 1.55);

    /* price: strike, count down, badge burst */
    tl.to(q("#s04strike"), { scaleX: 1, duration: 0.28, ease: "power2.out" }, T + 1.9);
    tl.to(q("#s04old"), { color: "#6e78a3", duration: 0.28 }, T + 1.9);
    tl.fromTo(q("#s04new"), { opacity: 0, x: 12 }, { opacity: 1, x: 0, duration: 0.35, ease: "power3.out" }, T + 2.05);
    NX.countMoney(tl, q("#s04big"), c.priceBefore, c.priceAfter, T + 1.95, 0.6);
    tl.to(q("#s04big"), { scale: 1.08, duration: 0.25, ease: "power2.out" }, T + 2.4);
    tl.to(q("#s04big"), { scale: 1, duration: 0.4, ease: "power2.inOut" }, T + 2.65);
    var badge = q("#s04badge");
    tl.fromTo(badge, { opacity: 0, scale: 0, rotation: -50 }, { opacity: 1, scale: 1, rotation: -12, duration: 0.6, ease: "back.out(2.2)" }, T + 2.2);
    NX.burst(tl, el, T + 2.25, { x: 1809, y: 707, n: 14, r: 170, c: "#8b5cf6", c2: "#5b9bff" });
    tl.to(badge, { scale: 1.06, duration: 0.45, ease: "sine.inOut", yoyo: true, repeat: 1 }, T + 2.85);

    /* exit: push into the "Left to pay" row (match-cut into beat 05) */
    tl.to(panel, { scale: 1.28, opacity: 0, transformOrigin: "88% 94%", duration: 0.45, ease: "power2.in" }, T + 3.6);
    tl.to(badge, { opacity: 0, scale: 1.3, duration: 0.3, ease: "power2.in" }, T + 3.6);
    tl.to(q("#s04l"), { opacity: 0, x: -60, duration: 0.4, ease: "power2.in" }, T + 3.6);
  }
});

