NX.scene({
  id: "s02",
  html: function (c) {
    var sel = c.game.cover, wall = NX.WALL.filter(function (f) { return f !== sel; });
    var rows = "";
    for (var r = 0; r < 4; r++) {
      rows += '<div class="s02row" style="display:flex;gap:20px;margin-left:' + (r % 2 ? 98 : 0) + 'px">';
      for (var i = 0; i < 8; i++) {
        var f = wall[(r * 8 + i) % wall.length];
        rows += '<img src="' + f + '" alt="" style="width:176px;height:264px;object-fit:cover;border-radius:14px;flex:none"/>';
      }
      rows += "</div>";
    }
    var nameSize = NX.fitSize(c.game.name, 700, 40, 26, 330, 1);
    return '' +
      '<div id="s02wall" style="position:absolute;left:700px;top:-170px;width:2200px;display:flex;flex-direction:column;gap:20px;transform:rotate(-12deg) skewX(-8deg);opacity:.5">' + rows + "</div>" +
      '<div id="s02sweep" style="position:absolute;left:0;top:-200px;width:260px;height:1480px;background:linear-gradient(90deg,rgba(157,133,255,0),rgba(190,170,255,.35),rgba(157,133,255,0));transform:skewX(-20deg);opacity:0"></div>' +
      '<div style="position:absolute;inset:0;background:linear-gradient(90deg,var(--abyss) 0,rgba(4,8,23,.92) 36%,rgba(4,8,23,0) 58%)"></div>' +
      '<div id="s02sel" style="position:absolute;left:1180px;top:230px;width:310px;height:465px;border-radius:22px;border:5px solid #9d85ff;box-shadow:0 0 0 8px rgba(139,92,246,.25),0 40px 100px rgba(0,0,0,.6),0 0 80px rgba(139,92,246,.55);overflow:hidden">' +
        '<img src="' + sel + '" alt="' + NX.esc(c.game.name) + '" style="width:100%;height:100%;object-fit:cover"/></div>' +
      '<div id="s02chk" style="position:absolute;left:1440px;top:204px;width:64px;height:64px;border-radius:50%;background:#6b4cf0;border:3px solid #fff;display:grid;place-items:center;color:#fff">' + NX.icon("check", "width:34px;height:34px") + "</div>" +
      '<div id="s02name" style="position:absolute;left:1160px;top:720px;width:350px;text-align:center;font:700 ' + nameSize + 'px/1.1 Geist;letter-spacing:-.02em">' + NX.esc(c.game.name) + "</div>" +
      NX.label({ id: "s02lbl", key: "l02", kick: "k02", top: 410 });
  },
