    tl.to(q("#s02sweep"), { opacity: 0, duration: 0.2 }, T + 1.7);
    tl.to(q("#s02wall"), { opacity: 0.32, duration: 0.5 }, T + 1.7);
    var sel = q("#s02sel");
    tl.fromTo(sel, { opacity: 0, scale: 0.55, y: 50, rotation: -6 }, { opacity: 1, scale: 1, y: 0, rotation: 0, duration: 0.65, ease: "back.out(1.6)" }, T + 1.75);
    tl.fromTo(q("#s02chk"), { opacity: 0, scale: 0 }, { opacity: 1, scale: 1, duration: 0.4, ease: "back.out(2.6)" }, T + 2.25);
    tl.fromTo(q("#s02name"), { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.4, ease: "power3.out" }, T + 2.3);
    /* seam: tile flies into the stepper's Game node (≈765,65); everything else exits left */
    tl.to([q("#s02chk"), q("#s02name")], { opacity: 0, duration: 0.2 }, T + 3.05);
    tl.to(sel, { x: 765 - 1335, y: 65 - 462, scale: 0.1, opacity: 0.2, duration: 0.5, ease: "power3.in" }, T + 3.1);
    tl.to(q("#s02wall"), { x: -700, opacity: 0, duration: 0.45, ease: "power3.in" }, T + 3.15);
    NX.labelOut(tl, q("#s02lbl"), T + 3.1);
  }
});

