    function card(id, flag, name, sub) {
      return '<div class="s03card" id="' + id + '" style="display:flex;align-items:center;gap:22px;padding:20px 24px;border-radius:18px;border:3px solid rgba(148,163,255,.28);background:rgba(10,16,48,.85)">' +
        '<img class="flag" src="assets/flags/' + flag + '.svg" style="width:60px;height:60px"/>' +
        '<div><div style="font:700 32px/1.1 Geist">' + name + '</div><div style="font:500 22px/1.3 Geist;color:var(--mist)">' + sub + "</div></div></div>";
    }
    return '' +
      '<div id="s03globe" style="position:absolute;left:1000px;top:210px;width:700px;height:700px">' +
