/* 06 · Live in seconds (15.0–19.0). The real "Building your server" checklist ticks through,
   the bar fills, then the "Your server is ready · ONLINE" stamp. */
NX.scene({
  id: "s06",
  html: function (c) {
    var steps = [["Allocating resources", "cpu"], ["Configuring network", "network"], ["Starting the machine", "bolt"], ["Booting the image", "download"],
      ["Waiting for network", "region"], ["Starting the game", "game"], ["Installing the game", "download"]];
    var rows = steps.map(function (s, i) {
      return '<div class="s06row" id="s06r' + i + '" style="position:relative;display:flex;align-items:center;gap:20px;height:68px;padding:0 20px;border-radius:14px;background:rgba(10,16,40,.6);border:2px solid rgba(148,163,255,.1)">' +
        '<span style="position:relative;width:40px;height:40px;flex:none"><span style="position:absolute;inset:0;border-radius:50%;border:3px solid rgba(148,163,255,.25)"></span>' +
        '<span class="s06chk" style="position:absolute;inset:0;border-radius:50%;border:3px solid var(--success);display:grid;place-items:center;color:var(--success);opacity:0">' + NX.icon("check", "width:24px;height:24px") + "</span></span>" +
        '<span class="s06t" style="flex:1;font:600 27px Geist;opacity:.45">' + s[0] + "</span>" + NX.icon(s[1], "width:36px;height:36px;color:var(--icon-blue);opacity:.6") + "</div>";
    }).join("");
    return '' +
      NX.label({ id: "s06lbl", key: "l06", kick: "k06", top: 400 }) +
      '<div class="panel" id="s06p" style="left:930px;top:150px;width:840px;height:880px;padding:30px 44px;display:flex;flex-direction:column;gap:12px">' +
        '<div style="align-self:center;width:104px;height:104px;border-radius:50%;background:radial-gradient(circle,rgba(107,76,240,.35),rgba(6,12,36,.9));border:2px solid rgba(157,133,255,.4);display:grid;place-items:center;color:#d6c8ff">' + NX.icon("game", "width:58px;height:58px") + "</div>" +
        '<div style="text-align:center;font:700 40px/1.1 Geist">Building your server</div>' +
        '<div style="display:flex;justify-content:space-between;font:500 22px Geist;color:var(--sky);margin-top:6px"><span id="s06stat">Allocating resources</span><span id="s06pct">0%</span></div>' +
        '<div style="height:10px;border-radius:999px;background:rgba(148,163,255,.14);overflow:hidden"><div id="s06bar" style="width:100%;height:100%;border-radius:999px;background:linear-gradient(90deg,#6b4cf0,#69a4d1);transform-origin:0 50%;transform:scaleX(0)"></div></div>' +
        '<div style="display:flex;flex-direction:column;gap:9px;margin-top:6px">' + rows + "</div>" +
