/* 05 · One click to deploy (13.0–15.0). Zoomed checkout: "Complete deployment →" is pressed,
   the ripple expands to fill the frame. */
NX.scene({
  id: "s05",
  html: function (c) {
    var E = NX.esc;
    return '' +
      NX.label({ id: "s05lbl", key: "l05", kick: "k05", top: 380 }) +
      '<div class="panel" id="s05p" style="left:900px;top:250px;width:920px;height:600px;padding:48px 50px;display:flex;flex-direction:column;gap:26px">' +
        '<div style="display:flex;justify-content:space-between;align-items:flex-end"><span style="font:700 40px Geist;padding-bottom:14px">Left to pay</span><span style="font:700 110px/1 Geist;color:var(--sky)">' + E(c.priceAfter) + "</span></div>" +
        '<div style="font:500 26px Geist;color:var(--haze);margin-top:-10px">Renews at ' + E(c.renewPrice) + "/mo after your first month.</div>" +
        '<div style="display:flex;align-items:center;gap:12px;font:500 26px Geist;color:var(--success)">' + NX.icon("check", "width:30px;height:30px") + "Creator code " + E(c.code) + " applied</div>" +
        '<div class="btn" id="s05btn" style="height:140px;font-size:46px;box-shadow:0 20px 60px rgba(107,59,219,.55),0 0 0 6px rgba(157,133,255,.25)">Complete deployment ' + NX.icon("arrow", "width:46px;height:46px") + "</div>" +
        '<div style="display:flex;justify-content:center;align-items:center;gap:12px;font:500 24px Geist;color:var(--haze)">' + NX.icon("lock", "width:28px;height:28px") + "Secure and encrypted checkout</div>" +
      "</div>" +
      '<div id="s05fill" style="position:absolute;left:1480px;top:700px;width:200px;height:200px;margin:-100px 0 0 -100px;border-radius:50%;background:#040817;box-shadow:0 0 0 6px rgba(139,92,246,.7),0 0 80px rgba(139,92,246,.6);opacity:0"></div>';
  },
  build: function (tl, c, el) {
    var T = 13.0, q = function (s) { return el.querySelector(s); };
    var p = q("#s05p"), btn = q("#s05btn");
    tl.fromTo(p, { opacity: 0, scale: 0.8, transformOrigin: "50% 40%" }, { opacity: 1, scale: 1, duration: 0.55, ease: "expo.out" }, T - 0.28);
    NX.labelIn(tl, q("#s05lbl"), T - 0.05);
    NX.cursorPath(tl, [{ t: T + 0.2, x: 1640, y: 860 }, { t: T + 0.72, x: 1480, y: 700, click: true }], { exit: T + 1.3 });
    NX.press(tl, btn, T + 0.72);
    tl.to(btn, { boxShadow: "0 20px 90px rgba(139,92,246,.95),0 0 0 10px rgba(179,160,255,.5)", duration: 0.2 }, T + 0.75);
    /* seam: the click ripple grows to cover the frame (becomes beat 06's background) */
    var fill = q("#s05fill");
    tl.fromTo(fill, { opacity: 0 }, { opacity: 1, duration: 0.05 }, T + 1.35);
    tl.fromTo(fill, { scale: 0.2 }, { scale: 22, duration: 0.6, ease: "power2.in" }, T + 1.35);
    NX.labelOut(tl, q("#s05lbl"), T + 1.3);
  }
});

