/* 07 · Your control panel (19.0–22.0). Server header with the creator's play address,
   stat strip; the tab rail (global) appears beneath and docks to the top. */
NX.scene({
  id: "s07",
  html: function (c) {
    var E = NX.esc;
    function stat(label, value, extra) {
      return '<div style="padding:22px;border-radius:16px;border:2px solid var(--ui-border);background:rgba(6,9,27,.7)"><div class="mono" style="font-size:18px;letter-spacing:.14em;color:var(--haze)">' + label + "</div>" +
        '<div style="display:flex;align-items:flex-end;gap:16px;margin-top:10px"><span style="font:700 40px Geist">' + value + "</span>" + (extra || "") + "</div>" +
        '<div style="height:6px;border-radius:9px;background:var(--ui-border);margin-top:14px"></div></div>';
    }
    var spark = '<svg width="130" height="40" viewBox="0 0 130 40"><polyline id="s07spark" points="0,36 30,35 55,34 70,33 80,20 88,30 96,8 104,31 130,30" fill="none" stroke="#8ea2ff" stroke-width="3" stroke-dasharray="190" stroke-dashoffset="190"/></svg>';
    var addrSize = NX.fitSize(c.playAddress, 500, 25, 18, 430, 1, true);
    return '' +
      NX.label({ id: "s07lbl", key: "l07", kick: "k07", top: 300, width: 600 }) +
      '<div id="s07cam" style="position:absolute;left:760px;top:190px;width:1240px;height:520px">' +
      '<div class="panel" id="s07p" style="left:0;top:0;width:1240px;height:520px;overflow:hidden">' +
        '<img src="' + c.game.cover + '" alt="" style="position:absolute;left:0;top:0;width:100%;height:200px;object-fit:cover;object-position:50% 30%;filter:blur(3px) brightness(.4)"/>' +
        '<div style="position:absolute;left:0;top:0;width:100%;height:200px;background:linear-gradient(180deg,rgba(5,13,31,0),rgba(5,13,31,.95))"></div>' +
        '<img src="' + c.game.cover + '" alt="" style="position:absolute;left:44px;top:70px;width:130px;height:130px;object-fit:cover;border-radius:22px;border:3px solid rgba(255,255,255,.18)"/>' +
        '<div style="position:absolute;left:200px;top:78px;display:flex;align-items:center;gap:18px"><span style="font:700 60px/1 Geist">My server</span>' +
          '<span class="pill" style="background:rgba(113,205,148,.16);border:2px solid rgba(113,205,148,.45);color:var(--success-soft);font-size:22px"><i id="s07dot" style="width:10px;height:10px;border-radius:50%;background:var(--success)"></i>Online</span></div>' +
        '<div style="position:absolute;left:200px;top:158px;display:flex;align-items:center;gap:22px;font:500 25px Geist;color:var(--mist);white-space:nowrap">' +
          '<b style="color:var(--ink);font-weight:600">' + E(c.game.name) + "</b>" +
          '<span id="s07addr" class="mono" style="position:relative;display:flex;align-items:center;gap:10px;font-size:' + addrSize + 'px;color:var(--sky)">' + E(c.playAddress) + NX.icon("copy", "width:26px;height:26px;color:var(--haze)") +
            '<i id="s07ul" style="position:absolute;left:0;right:36px;bottom:-6px;height:3px;border-radius:2px;background:var(--nx-soft);transform-origin:0 50%;transform:scaleX(0)"></i></span>' +
          '<span style="display:flex;align-items:center;gap:10px"><img class="flag" src="assets/flags/ca.svg" style="width:30px;height:30px"/>Beauharnois, CA</span></div>' +
        '<div style="position:absolute;right:70px;top:36px;display:flex;gap:12px">' +
          '<span class="pill" style="padding:12px 18px;border:2px solid var(--ui-border);color:var(--haze);font-size:22px">' + NX.icon("play", "width:22px;height:22px") + "Start</span>" +
