input.content:
/* 08 · Tweak every setting (22.0–24.5). Minecraft settings block (real labels); the cursor flips
   "Allow flight" on and switches Difficulty Easy → Normal; "Saved" pops. */
NX.scene({
  id: "s08",
  html: function (c) {
    var title = c.isMC ? "Minecraft settings" : "Server settings";
    function drop(label, inner, id, extra) {
      return '<div><div style="font:600 25px Geist;margin-bottom:12px">' + label + '</div><div id="' + id + '" style="position:relative;display:flex;justify-content:space-between;align-items:center;height:70px;padding:0 22px;border-radius:14px;border:3px solid rgba(148,163,255,.28);background:rgba(6,9,27,.8);font:500 27px Geist' + (extra || "") + '">' + inner + "</div></div>";
    }
    function tog(label, on, id) {
      return '<div id="' + id + '" style="display:flex;align-items:center;justify-content:space-between;padding:22px 24px;border-radius:16px;border:3px solid rgba(148,163,255,.14);background:rgba(6,9,27,.7)"><span style="font:600 26px Geist">' + label + '</span><span class="tog' + (on ? " on" : "") + '"><i class="k"></i></span></div>';
    }
    return '' +
      NX.label({ id: "s08lbl", key: "l08", kick: "k08", top: 360, width: 660 }) +
      '<div class="panel" id="s08p" style="left:860px;top:160px;width:1000px;height:850px;padding:40px 44px;display:flex;flex-direction:column;gap:22px">' +
        '<div style="display:flex;align-items:center;gap:18px"><span style="width:64px;height:64px;border-radius:16px;background:rgba(107,76,240,.2);border:2px solid rgba(157,133,255,.4);display:grid;place-items:center;color:#c9b8ff">' + NX.icon("game", "width:38px;height:38px") + "</span>" +
          '<div><div style="font:700 36px/1.1 Geist">' + title + '</div><div style="font:500 22px Geist;color:var(--haze)">This game\'s own options</div></div></div>' +
        '<div class="mono" style="font-size:20px;letter-spacing:.16em;color:var(--haze);margin-top:6px">GAMEPLAY</div>' +
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:22px">' +
          drop("Default game mode", 'Survival<span style="color:var(--haze)">▾</span>', "s08mode") +
          drop("Difficulty", '<span style="position:relative;display:block;height:34px;flex:1"><span id="s08easy" style="position:absolute;left:0;top:0">Easy</span><span id="s08norm" style="position:absolute;left:0;top:0;opacity:0">Normal</span></span><span style="color:var(--haze)">▾</span>', "s08diff") +
        "</div>" +
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:18px">' +
          tog("Player vs player", true, "s08pvp") + tog("Spawn monsters", true, "s08mob") + tog("Allow flight", false, "s08fly") + tog("Hardcore", false, "s08hc") +
        "</div>" +
        '<div class="mono" style="font-size:20px;letter-spacing:.16em;color:var(--haze);margin-top:6px">ACCESS</div>' +
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:end">' +
          drop("Max players", "20", "s08max") + tog("Whitelist", false, "s08wl") +
        "</div>" +
      "</div>" +
      '<div id="s08saved" style="position:absolute;left:1640px;top:938px;display:flex;align-items:center;gap:10px;padding:14px 22px;border-radius:999px;background:rgba(8,36,24,.96);border:2px solid var(--success);color:var(--success-soft);font:600 24px Geist;opacity:0">' + NX.icon("check", "width:26px;height:26px") + "Saved</div>";
  },
  build: function (tl, c, el) {
    var T = 22.0, q = function (s) { return el.querySelector(s); };
    var p = q("#s08p");
    NX.panelIn(tl, p, T - 0.3);
    NX.labelIn(tl, q("#s08lbl"), T - 0.05);
    NX.cursorPath(tl, [{ t: T + 0.15, x: 1500, y: 900 }, { t: T + 0.6, x: 1288, y: 631, click: true }, { t: T + 1.3, x: 1640, y: 412, click: true }], { exit: T + 2.15 });
    /* Allow flight: off → on */
    var fly = q("#s08fly"), tg = fly.querySelector(".tog"), k = fly.querySelector(".k");
    tl.to(tg, { backgroundColor: "#5b3fe0", borderColor: "#9d85ff", duration: 0.2 }, T + 0.62);
    tl.to(k, { x: 34, backgroundColor: "#e9e4ff", duration: 0.28, ease: "back.out(2)" }, T + 0.62);
    tl.to(fly, { borderColor: "#9d85ff", backgroundColor: "#151039", boxShadow: "0 0 30px rgba(139,92,246,.35)", duration: 0.25 }, T + 0.62);
    /* Difficulty: Easy → Normal */
    var diff = q("#s08diff");
    tl.to(diff, { borderColor: "#9d85ff", boxShadow: "0 0 28px rgba(139,92,246,.4)", duration: 0.2 }, T + 1.32);
    tl.to(q("#s08easy"), { opacity: 0, y: -18, duration: 0.2 }, T + 1.36);
    tl.fromTo(q("#s08norm"), { opacity: 0, y: 18 }, { opacity: 1, y: 0, duration: 0.25, ease: "power3.out", immediateRender: false }, T + 1.42);
    tl.fromTo(q("#s08saved"), { opacity: 0, scale: 0.6 }, { opacity: 1, scale: 1, duration: 0.35, ease: "back.out(2.4)" }, T + 1.6);
    /* seam */
    NX.labelOut(tl, q("#s08lbl"), T + 2.2);
    NX.pushOut(tl, p, T + 2.22);
