    tl.fromTo(q("#s08norm"), { opacity: 0, y: 18 }, { opacity: 1, y: 0, duration: 0.25, ease: "power3.out", immediateRender: false }, T + 1.42);
    tl.fromTo(q("#s08saved"), { opacity: 0, scale: 0.6 }, { opacity: 1, scale: 1, duration: 0.35, ease: "back.out(2.4)" }, T + 1.6);
