          drop("Difficulty", '<span style="position:relative;display:block;height:34px;flex:1"><span id="s08easy" style="position:absolute;left:0;top:0">Easy</span><span id="s08norm" style="position:absolute;left:0;top:0;opacity:0">Normal</span></span><span style="color:var(--haze)">▾</span>', "s08diff") +
        "</div>" +
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:18px">' +
          tog("Player vs player", true, "s08pvp") + tog("Spawn monsters", true, "s08mob") + tog("Allow flight", false, "s08fly") + tog("Hardcore", false, "s08hc") +
        "</div>" +
        '<div class="mono" style="font-size:20px;letter-spacing:.16em;color:var(--haze);margin-top:6px">ACCESS</div>' +
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:end">' +
          drop("Max players", "20", "s08max") + tog("Whitelist", false, "s08wl") +
        "</div>" +
      "</div>" +
      '<div id="s08saved" style="position:absolute;left:1640px;top:938px;display:flex;align-items:center;gap:10px;padding:14px 22px;border-radius:999px;background:rgba(8,36,24,.96);border:2px solid var(--success);color:var(--success-soft);font:600 24px Geist;opacity:0">' + NX.icon("check", "width:26px;height:26px") + "Saved</div>";
  },
  build: function (tl, c, el) {
    var T = 22.0, q = function (s) { return el.querySelector(s); };
    var p = q("#s08p");
    NX.panelIn(tl, p, T - 0.3);
    NX.labelIn(tl, q("#s08lbl"), T - 0.05);
    NX.cursorPath(tl, [{ t: T + 0.15, x: 1500, y: 900 }, { t: T + 0.6, x: 1288, y: 631, click: true }, { t: T + 1.3, x: 1640, y: 412, click: true }], { exit: T + 2.15 });
    /* Allow flight: off → on */
    var fly = q("#s08fly"), tg = fly.querySelector(".tog"), k = fly.querySelector(".k");
    tl.to(tg, { backgroundColor: "#5b3fe0", borderColor: "#9d85ff", duration: 0.2 }, T + 0.62);
    tl.to(k, { x: 34, backgroundColor: "#e9e4ff", duration: 0.28, ease: "back.out(2)" }, T + 0.62);
    tl.to(fly, { borderColor: "#9d85ff", backgroundColor: "#151039", boxShadow: "0 0 30px rgba(139,92,246,.35)", duration: 0.25 }, T + 0.62);
    /* Difficulty: Easy → Normal */
    var diff = q("#s08diff");
    tl.to(diff, { borderColor: "#9d85ff", boxShadow: "0 0 28px rgba(139,92,246,.4)", duration: 0.2 }, T + 1.32);
    tl.to(q("#s08easy"), { opacity: 0, y: -18, duration: 0.2 }, T + 1.36);
    tl.fromTo(q("#s08norm"), { opacity: 0, y: 18 }, { opacity: 1, y: 0, duration: 0.25, ease: "power3.out", immediateRender: false }, T + 1.42);
    tl.fromTo(q("#s08saved"), { opacity: 0, scale: 0.6 }, { opacity: 1, scale: 1, duration: 0.35, ease: "back.out(2.4)" }, T + 1.6);
    /* seam */
    NX.labelOut(tl, q("#s08lbl"), T + 2.2);
    NX.pushOut(tl, p, T + 2.22);
    tl.to(q("#s08saved"), { opacity: 0, duration: 0.2 }, T + 2.2);
  }
});

/* 09 · 1-click mods (24.5–27.5). Real mod cards ("FITS YOUR SERVER"); Install on VeinMiner →
   "Writing files to your server" bar → "Installed ✓" + 1-CLICK badge. Icons cropped from the product. */
NX.scene({
  id: "s09",
  html: function (c) {
    var mods = [["veinminer", "VeinMiner", "Miraculixx", "88M"], ["dungeons-and-taverns", "Dungeons and Taverns", "NovaWostra", "21M"], ["towns-and-towers", "Towns and Towers", "Biban_Auriu", "18M"],
      ["tectonic", "Tectonic", "Apollo", "17M"], ["geophilic", "Geophilic", "bebebe_loste", "11M"], ["structory", "Structory", "Starmute", "8.6M"]];
    var cards = mods.map(function (m, i) {
      return '<div class="s09card" id="s09c' + i + '" style="position:relative;padding:22px;border-radius:18px;border:3px solid rgba(148,163,255,.14);background:rgba(6,9,27,.78)">' +
        '<img src="assets/mods/' + m[0] + '.png" alt="" style="width:72px;height:72px;border-radius:14px"/>' +
        '<div style="font:700 27px/1.15 Geist;margin-top:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + m[1] + "</div>" +
        '<div style="font:500 18px Geist;color:var(--haze)">by ' + m[2] + " · Mods</div>" +
        '<div class="pill mono" style="margin-top:10px;background:rgba(113,205,148,.14);color:var(--success-soft);font-size:15px;letter-spacing:.06em;padding:6px 10px">' + NX.icon("check", "width:16px;height:16px") + "FITS YOUR SERVER</div>" +
        '<div style="display:flex;align-items:center;justify-content:space-between;margin-top:12px"><span style="font:500 20px Geist;color:var(--mist)">↓ ' + m[3] + "</span>" +
          '<span style="position:relative;display:inline-block">' +
            '<span class="s09inst pill" style="background:var(--install);color:#fff;font-size:22px;padding:10px 18px;border-radius:12px">Install</span>' +
            (i === 0 ? '<span id="s09done" class="pill" style="position:absolute;right:0;top:0;background:var(--success);color:#062014;font-size:22px;padding:10px 16px;border-radius:12px;white-space:nowrap;opacity:0">Installed' + NX.icon("check", "width:20px;height:20px") + "</span>" : "") +
          "</span></div>" +
        (i === 0 ? '<span id="s09badge" class="pill" style="position:absolute;right:-14px;top:-18px;background:linear-gradient(90deg,#5b9bff,#8b5cf6);color:#fff;font:800 24px/1 Geist;padding:12px 16px;box-shadow:0 10px 30px rgba(107,59,219,.6);opacity:0">1-CLICK</span>' : "") +
        "</div>";
    }).join("");
    return '' +
      NX.label({ id: "s09lbl", key: "l09", kick: "k09", top: 400, width: 680 }) +
      '<div class="panel" id="s09p" style="left:820px;top:150px;width:1060px;height:870px;padding:34px 40px;display:flex;flex-direction:column;gap:20px">' +
        '<div style="display:flex;align-items:center;gap:18px"><span style="width:64px;height:64px;border-radius:16px;background:linear-gradient(135deg,#5b9bff,#8b5cf6);display:grid;place-items:center;color:#fff">' + NX.icon("cube", "width:38px;height:38px") + "</span>" +
          '<div><div style="font:700 36px/1.1 Geist">Mods &amp; Plugins</div><div style="display:flex;gap:14px;margin-top:6px;font:500 22px Geist;color:var(--mist)"><span>vanilla · 26.3</span><span style="color:#8ea2ff">⚡ One-click</span></div></div></div>' +
        '<div id="s09prog" style="padding:16px 20px;border-radius:14px;border:2px solid rgba(157,133,255,.45);background:rgba(20,24,64,.6);opacity:0">' +
          '<div style="position:relative;height:30px;font:600 23px Geist"><span id="s09pt" style="position:absolute;left:0;top:0;color:#c9b8ff">VeinMiner: Writing files to your server</span><span id="s09pt2" style="position:absolute;left:0;top:0;color:var(--success-soft);opacity:0">VeinMiner installed — it appears under Installed.</span><span id="s09pp" style="position:absolute;right:0;top:0;color:#c9b8ff">0%</span></div>' +
          '<div style="height:8px;border-radius:9px;background:rgba(148,163,255,.14);margin-top:12px;overflow:hidden"><div id="s09bar" style="width:100%;height:100%;border-radius:9px;background:linear-gradient(90deg,#6b4cf0,#69a4d1);transform-origin:0 50%;transform:scaleX(0)"></div></div></div>' +
        '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:18px">' + cards + "</div>" +
      "</div>";
  },
  build: function (tl, c, el) {
    var T = 24.5, q = function (s) { return el.querySelector(s); };
    var p = q("#s09p");
    NX.panelIn(tl, p, T - 0.3);
    NX.labelIn(tl, q("#s09lbl"), T - 0.05);
    tl.fromTo(el.querySelectorAll(".s09card"), { opacity: 0, y: 40, scale: 0.94 }, { opacity: 1, y: 0, scale: 1, duration: 0.5, ease: "expo.out", stagger: 0.06 }, T + 0.0);
    var inst = q("#s09c0 .s09inst");
    var r = inst.getBoundingClientRect ? null : null;
    NX.cursorPath(tl, [{ t: T + 0.2, x: 1150, y: 860 }, { t: T + 0.62, x: 1110, y: 616, click: true }], { exit: T + 2.3 });
    NX.press(tl, inst, T + 0.62);
    var prog = q("#s09prog"), pv = { v: 0 }, pp = q("#s09pp");
    tl.fromTo(prog, { opacity: 0, y: -10 }, { opacity: 1, y: 0, duration: 0.3, ease: "power3.out" }, T + 0.7);
    tl.fromTo(q("#s09bar"), { scaleX: 0 }, { scaleX: 1, duration: 1.25, ease: "power1.inOut" }, T + 0.75);
    tl.to(pv, { v: 100, duration: 1.25, ease: "power1.inOut", onUpdate: function () { pp.textContent = Math.round(pv.v) + "%"; } }, T + 0.75);
    tl.to(prog, { borderColor: "rgba(113,205,148,.55)", backgroundColor: "rgba(8,36,24,.6)", duration: 0.25 }, T + 2.0);
    tl.to(q("#s09pt"), { opacity: 0, duration: 0.15 }, T + 2.0);
    tl.to(pp, { opacity: 0, duration: 0.15 }, T + 2.0);
    tl.fromTo(q("#s09pt2"), { opacity: 0 }, { opacity: 1, duration: 0.25, immediateRender: false }, T + 2.05);
    tl.to(q("#s09bar"), { background: "#71cd94", duration: 0.25 }, T + 2.0);
    var card = q("#s09c0");
    tl.to(card, { borderColor: "#71cd94", backgroundColor: "rgba(8,30,22,.8)", boxShadow: "0 0 40px rgba(113,205,148,.3)", duration: 0.3 }, T + 2.05);
    tl.to(inst, { opacity: 0, duration: 0.15 }, T + 2.05);
    tl.fromTo(q("#s09done"), { opacity: 0, scale: 0.7 }, { opacity: 1, scale: 1, duration: 0.35, ease: "back.out(2.4)", immediateRender: false }, T + 2.08);
    tl.fromTo(q("#s09badge"), { opacity: 0, scale: 0, rotation: -20 }, { opacity: 1, scale: 1, rotation: 8, duration: 0.45, ease: "back.out(2.6)", immediateRender: false }, T + 2.15);
    NX.burst(tl, el, T + 2.2, { x: 1170, y: 400, n: 12, r: 140, c: "#5b9bff", c2: "#8b5cf6" });
    /* seam */
    NX.labelOut(tl, q("#s09lbl"), T + 2.62);
    NX.pushOut(tl, p, T + 2.64);
  }
});

