/* 10 · Live resource stats (27.5–30.0). CPU + Memory graphs draw on (shapes from the recording);
   a readout rides the memory front and turns amber near the limit. */
NX.scene({
  id: "s10",
  cpu: [[0, 200], [560, 200], [600, 196], [640, 170], [670, 192], [700, 150], [730, 186], [760, 92], [790, 180], [830, 120], [860, 176], [900, 64], [940, 150]],
  mem: [[0, 200], [600, 200], [640, 180], [680, 172], [720, 150], [760, 136], [790, 70], [840, 52], [900, 47]],
  html: function (c) {
    var self = this;
    function pts(a) { return a.map(function (p) { return p.join(","); }).join(" "); }
    function len(a) { var L = 0; for (var i = 1; i < a.length; i++) L += Math.hypot(a[i][0] - a[i - 1][0], a[i][1] - a[i - 1][1]); return Math.ceil(L); }
    function graph(id, a, stroke, fill) {
      var area = "M" + a.map(function (p) { return p.join(","); }).join(" L") + " L" + a[a.length - 1][0] + ",200 Z";
      return '<svg width="940" height="230" viewBox="0 0 940 230" style="margin-top:10px;overflow:visible">' +
        '<g stroke="rgba(148,163,255,.12)" stroke-width="2"><line x1="0" y1="20" x2="940" y2="20"/><line x1="0" y1="80" x2="940" y2="80"/><line x1="0" y1="140" x2="940" y2="140"/><line x1="0" y1="200" x2="940" y2="200"/></g>' +
        '<path id="' + id + 'a" d="' + area + '" fill="' + fill + '" opacity="0"/>' +
        '<polyline id="' + id + 'l" points="' + pts(a) + '" fill="none" stroke="' + stroke + '" stroke-width="4" stroke-linejoin="round" stroke-dasharray="' + len(a) + '" stroke-dashoffset="' + len(a) + '"/>' +
        (id === "s10m" ? '<line id="s10scrub" x1="0" y1="10" x2="0" y2="210" stroke="rgba(245,180,83,.85)" stroke-width="3" stroke-dasharray="8 8" opacity="0"/><circle id="s10dot" cx="0" cy="200" r="10" fill="#f5b453" opacity="0"/>' : "") +
        "</svg>";
    }
    return '' +
      NX.label({ id: "s10lbl", key: "l10", kick: "k10", top: 340, width: 680 }) +
      '<div class="panel" id="s10p" style="left:820px;top:150px;width:1060px;height:870px;padding:34px 40px;display:flex;flex-direction:column;gap:22px">' +
        '<div style="display:flex;justify-content:space-between;align-items:center"><span style="font:700 36px Geist">Resource usage</span><span style="display:flex;gap:8px;font:600 20px Geist;color:var(--haze)"><span style="padding:8px 14px">1h</span><span style="padding:8px 14px">6h</span><span style="padding:8px 14px;border-radius:10px;background:#5b3fe0;color:#fff">24h</span><span style="padding:8px 14px">7d</span><span style="padding:8px 14px">30d</span></span></div>' +
        '<div style="padding:24px 26px;border-radius:18px;border:2px solid var(--ui-border);background:rgba(6,9,27,.75)"><div style="display:flex;justify-content:space-between"><span style="font:600 26px Geist">CPU usage</span><span id="s10cv" style="font:700 30px Geist;color:#8ea2ff">0%</span></div>' + graph("s10c", self.cpu, "#8ea2ff", "rgba(139,92,246,.22)") + "</div>" +
        '<div style="padding:24px 26px;border-radius:18px;border:2px solid var(--ui-border);background:rgba(6,9,27,.75)"><div style="display:flex;justify-content:space-between"><span style="font:600 26px Geist">Memory</span><span id="s10mv" style="font:700 30px Geist;color:#5b9bff">0.0 / 2.0 GB</span></div>' + graph("s10m", self.mem, "#5b9bff", "rgba(91,155,255,.22)") + "</div>" +
      "</div>";
  },
  build: function (tl, c, el) {
    var T = 27.5, q = function (s) { return el.querySelector(s); }, self = this;
    var p = q("#s10p");
    NX.panelIn(tl, p, T - 0.3);
    NX.labelIn(tl, q("#s10lbl"), T - 0.05);
    tl.to(q("#s10cl"), { strokeDashoffset: 0, duration: 1.1, ease: "power1.inOut" }, T + 0.15);
    tl.to(q("#s10ca"), { opacity: 1, duration: 0.5 }, T + 0.9);
    tl.to(q("#s10ml"), { strokeDashoffset: 0, duration: 1.2, ease: "power1.inOut" }, T + 0.3);
    tl.to(q("#s10ma"), { opacity: 1, duration: 0.5 }, T + 1.1);
    /* readouts: CPU climbs to 12%, memory front dot + scrub ride the line */
    var cv = q("#s10cv"), cp = { v: 0 };
    tl.to(cp, { v: 12, duration: 1.1, ease: "power1.inOut", onUpdate: function () { cv.textContent = Math.round(cp.v) + "%"; } }, T + 0.15);
    var a = self.mem, segs = [], L = 0;
    for (var i = 1; i < a.length; i++) { var d = Math.hypot(a[i][0] - a[i - 1][0], a[i][1] - a[i - 1][1]); segs.push([L, d, a[i - 1], a[i]]); L += d; }
    var dot = q("#s10dot"), scrub = q("#s10scrub"), mv = q("#s10mv"), mp = { v: 0 };
    tl.fromTo([dot, scrub], { opacity: 0 }, { opacity: 1, duration: 0.2 }, T + 0.3);
    tl.to(mp, { v: 1, duration: 1.2, ease: "power1.inOut", onUpdate: function () {
      var at = mp.v * L, s = segs[segs.length - 1];
      for (var j = 0; j < segs.length; j++) if (at <= segs[j][0] + segs[j][1]) { s = segs[j]; break; }
      var k = Math.max(0, Math.min(1, (at - s[0]) / s[1])), x = s[2][0] + (s[3][0] - s[2][0]) * k, y = s[2][1] + (s[3][1] - s[2][1]) * k;
      dot.setAttribute("cx", x.toFixed(1)); dot.setAttribute("cy", y.toFixed(1));
      scrub.setAttribute("x1", x.toFixed(1)); scrub.setAttribute("x2", x.toFixed(1));
      var gb = 2.0 * (200 - y) / 200 * 0.8; mv.textContent = gb.toFixed(1) + " / 2.0 GB";
    } }, T + 0.3);
    tl.to(mv, { color: "#f5b453", duration: 0.3 }, T + 1.25);
    /* seam */
    NX.labelOut(tl, q("#s10lbl"), T + 2.12);
    NX.pushOut(tl, p, T + 2.14);
  }
});

