/* 11 · Upgrade instantly (30.0–33.0). Real "Upgrade your server" block: current 2 GB tier →
   pick 4 GB → "Upgrade for $4.05" → burst, RAM chip counts 2 → 4 GB. */
NX.scene({
  id: "s11",
  html: function (c) {
    var E = NX.esc, g = c.game.name;
    function row(id, name, specs, price, cur) {
      return '<div id="' + id + '" style="padding:20px 24px;border-radius:16px;border:3px solid rgba(148,163,255,.14);background:rgba(6,9,27,.75)">' +
        '<div style="display:flex;justify-content:space-between;align-items:center"><span style="display:flex;align-items:center;gap:14px;font:700 28px Geist">' + E(name) +
        (cur ? '<span class="pill mono" style="background:rgba(186,161,244,.16);color:var(--lavender);font-size:17px;letter-spacing:.1em;padding:8px 12px">CURRENT TIER</span>' : "") +
        '</span><span style="font:600 26px Geist">' + E(price) + '/mo</span></div><div style="font:500 21px Geist;color:var(--haze);margin-top:8px">' + specs + "</div></div>";
    }
    return '' +
      NX.label({ id: "s11lbl", key: "l11", kick: "k11", top: 380, width: 680 }) +
      '<div class="panel" id="s11p" style="left:820px;top:150px;width:1060px;height:870px;padding:36px 40px;display:flex;flex-direction:column;gap:18px">' +
        '<div style="display:flex;align-items:center;gap:16px"><span style="width:60px;height:60px;border-radius:16px;background:rgba(107,76,240,.2);border:2px solid rgba(157,133,255,.4);display:grid;place-items:center;color:#c9b8ff">' + NX.icon("bolt", "width:34px;height:34px") + '</span><span style="font:700 38px Geist">Upgrade your server</span></div>' +
        '<div style="font:500 24px/1.4 Geist;color:var(--mist)">Move to a bigger tier and pay only the difference. Your world, files and settings stay exactly as they are.</div>' +
        row("s11r2", g + " — 2 GB", "2 vCPU · 2 GB RAM · 20 GB NVMe · ~9 players recommended", c.renewPrice, true) +
        row("s11r4", g + " — 4 GB", '2 vCPU · <b id="s11ram" style="color:var(--mist);font-weight:500">4 GB RAM</b> · 30 GB NVMe · ~20 players recommended', c.upgradeRenew, false) +
        row("s11r8", g + " — 8 GB", "3 vCPU · 8 GB RAM · 50 GB NVMe · ~50 players recommended", c.tier8Price, false) +
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-top:4px"><span style="font:500 24px Geist;color:var(--mist)">Due now, for the rest of your term</span><span style="font:700 52px Geist">' + E(c.upgradePrice) + "</span></div>" +
        '<div class="btn" id="s11btn" style="height:96px;width:440px;font-size:32px;box-shadow:0 18px 50px rgba(107,59,219,.5)">Upgrade for ' + E(c.upgradePrice) + "</div>" +
      "</div>" +
      '<div id="s11chip" style="position:absolute;left:1360px;top:900px;display:flex;align-items:center;gap:14px;padding:16px 24px;border-radius:999px;background:rgba(8,36,24,.96);border:3px solid var(--success);box-shadow:0 0 40px rgba(113,205,148,.4);opacity:0">' +
        NX.icon("memory", "width:34px;height:34px;color:var(--success-soft)") + '<span id="s11gb" style="font:700 32px Geist;color:var(--success-soft);white-space:nowrap">2 GB RAM</span></div>';
  },
  build: function (tl, c, el) {
    var T = 30.0, q = function (s) { return el.querySelector(s); };
    var p = q("#s11p");
    NX.panelIn(tl, p, T - 0.3);
    NX.labelIn(tl, q("#s11lbl"), T - 0.05);
    NX.cursorPath(tl, [{ t: T + 0.15, x: 1560, y: 760 }, { t: T + 0.55, x: 1500, y: 540, click: true }, { t: T + 1.2, x: 1240, y: 876, click: true }], { exit: T + 2.3 });
    var r4 = q("#s11r4");
    tl.to(r4, { borderColor: "#9d85ff", backgroundColor: "#151039", boxShadow: "0 0 40px rgba(139,92,246,.4)", duration: 0.25 }, T + 0.58);
    tl.to(q("#s11ram"), { color: "#9aeebc", fontWeight: 700, duration: 0.25 }, T + 0.58);
    var btn = q("#s11btn");
    NX.press(tl, btn, T + 1.2);
    tl.to(btn, { boxShadow: "0 18px 80px rgba(139,92,246,.95),0 0 0 8px rgba(179,160,255,.45)", duration: 0.2 }, T + 1.22);
    NX.burst(tl, el, T + 1.25, { x: 1240, y: 876, n: 14, r: 170, c: "#b3a0ff", c2: "#71cd94" });
    var chip = q("#s11chip"), gbEl = q("#s11gb"), gb = { v: 2 };
    tl.fromTo(chip, { opacity: 0, scale: 0.6, y: 20 }, { opacity: 1, scale: 1, y: 0, duration: 0.45, ease: "back.out(2.2)" }, T + 1.4);
    tl.to(gb, { v: 4, duration: 0.6, ease: "power2.inOut", onUpdate: function () { gbEl.textContent = (gb.v < 3.995 ? "2 GB → " + Math.round(gb.v) : "2 GB → 4") + " GB RAM"; } }, T + 1.55);
    /* hide under the wipe (cut_at 32.85) */
    tl.to([p, chip, q("#s11lbl")], { opacity: 0, duration: 0.01 }, 32.86);
  }
});

