      var k = Math.max(0, Math.min(1, (at - s[0]) / s[1])), x = s[2][0] + (s[3][0] - s[2][0]) * k, y = s[2][1] + (s[3][1] - s[2][1]) * k;
      dot.setAttribute("cx", x.toFixed(1)); dot.setAttribute("cy", y.toFixed(1));
      scrub.setAttribute("x1", x.toFixed(1)); scrub.setAttribute("x2", x.toFixed(1));
      var gb = 2.0 * (200 - y) / 200 * 0.8; mv.textContent = gb.toFixed(1) + " / 2.0 GB";
