    return '' +
      '<div id="s12in" style="position:absolute;inset:0">' +
      '<img id="s12wall" src="assets/brand/wallpaper.png" alt="" style="position:absolute;inset:0;width:1920px;height:1080px;object-fit:cover;filter:brightness(.3) saturate(1.1)"/>' +
      '<div style="position:absolute;inset:0;background:radial-gradient(1100px 640px at 50% 52%,rgba(4,8,23,.55),rgba(4,8,23,.92) 78%)"></div>' +
      '<img id="s12logo" src="assets/brand/logo-lockup.png" alt="NXEON" style="position:absolute;left:640px;top:96px;width:640px;height:111px"/>' +
      '<div id="s12kick" class="mono" style="position:absolute;left:0;right:0;top:290px;text-align:center;font-size:30px;line-height:1;letter-spacing:.4em;color:var(--mist)">' + E(kick) + "</div>" +
      '<div style="position:absolute;left:0;right:0;top:340px;height:200px;display:flex;justify-content:center"><div id="s12chip" class="chipcode" style="width:' + chipW + 'px;height:200px;justify-content:center;gap:34px;border-width:5px;box-shadow:0 0 80px rgba(139,92,246,.6),inset 0 0 50px rgba(91,155,255,.2)">' +
        NX.icon("tag", "width:96px;height:96px;color:#b3a0ff") +
        (c.generic ? '<span style="width:640px"></span>' : '<span style="font:800 ' + codeSize + 'px/1 Geist;letter-spacing:-.02em;white-space:nowrap">' + E(c.code) + "</span>") +
      "</div></div>" +
      '<div id="s12e1" style="position:absolute;left:0;right:0;top:600px;text-align:center;font:700 ' + e1Size + 'px/1.05 Geist;letter-spacing:-.035em">' + NX.hl("end1").replace(/<em>/g, '<em style="font-style:normal;color:var(--nx-soft)">') + "</div>" +
