      '<div id="s12tag" style="position:absolute;right:96px;top:964px;font:600 ' + tagSize + 'px Geist;letter-spacing:-.02em;white-space:nowrap">' + NX.hl("tagline").replace(/<em>/g, '<em style="font-style:normal;color:var(--nx-soft)">') + "</div>" +
      "</div>";
  },
