    tl.fromTo(q("#s12logo"), { opacity: 0, y: -24 }, { opacity: 1, y: 0, duration: 0.5, ease: "power3.out" }, T + 0.15);
    tl.fromTo(q("#s12kick"), { opacity: 0, letterSpacing: "0.8em" }, { opacity: 1, letterSpacing: "0.4em", duration: 0.6, ease: "expo.out" }, T + 0.4);
