    tl.to(q("#s12chip"), { boxShadow: "0 0 120px rgba(139,92,246,.85),inset 0 0 60px rgba(91,155,255,.3)", duration: 0.5, ease: "sine.inOut", yoyo: true, repeat: 1 }, T + 1.3);
    tl.fromTo(q("#s12e1"), { opacity: 0, y: 26 }, { opacity: 1, y: 0, duration: 0.5, ease: "power3.out" }, T + 1.05);
    tl.fromTo(q("#s12e2"), { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.45, ease: "power3.out" }, T + 1.2);
    tl.fromTo(q("#s12url"), { opacity: 0, scale: 0.85 }, { opacity: 1, scale: 1, duration: 0.5, ease: "back.out(2)" }, T + 1.45);
    if (q("#s12h")) tl.fromTo(q("#s12h"), { opacity: 0 }, { opacity: 1, duration: 0.4 }, T + 1.65);
    tl.fromTo(el.querySelectorAll(".s12g"), { opacity: 0, y: 24 }, { opacity: 1, y: 0, duration: 0.45, ease: "back.out(2)", stagger: 0.06 }, T + 1.75);
    tl.fromTo(q("#s12games span"), { opacity: 0 }, { opacity: 1, duration: 0.4 }, T + 2.1);
    tl.fromTo(q("#s12tag"), { opacity: 0, x: 30 }, { opacity: 1, x: 0, duration: 0.5, ease: "power3.out" }, T + 2.15);
    /* 36.0–37.5: held still frame (nothing animates after T + 2.9) */
  }
});

