      '<div id="s11chip" style="position:absolute;left:1360px;top:900px;display:flex;align-items:center;gap:14px;padding:16px 24px;border-radius:999px;background:rgba(8,36,24,.96);border:3px solid var(--success);box-shadow:0 0 40px rgba(113,205,148,.4);opacity:0">' +
        NX.icon("memory", "width:34px;height:34px;color:var(--success-soft)") + '<span id="s11gb" style="font:700 32px Geist;color:var(--success-soft);white-space:nowrap">2 GB RAM</span></div>';
  },
  build: function (tl, c, el) {
    var T = 30.0, q = function (s) { return el.querySelector(s); };
    var p = q("#s11p");
    NX.panelIn(tl, p, T - 0.3);
    NX.labelIn(tl, q("#s11lbl"), T - 0.05);
    NX.cursorPath(tl, [{ t: T + 0.15, x: 1560, y: 760 }, { t: T + 0.55, x: 1500, y: 540, click: true }, { t: T + 1.2, x: 1240, y: 876, click: true }], { exit: T + 2.3 });
    var r4 = q("#s11r4");
    tl.to(r4, { borderColor: "#9d85ff", backgroundColor: "#151039", boxShadow: "0 0 40px rgba(139,92,246,.4)", duration: 0.25 }, T + 0.58);
    tl.to(q("#s11ram"), { color: "#9aeebc", fontWeight: 700, duration: 0.25 }, T + 0.58);
    var btn = q("#s11btn");
    NX.press(tl, btn, T + 1.2);
    tl.to(btn, { boxShadow: "0 18px 80px rgba(139,92,246,.95),0 0 0 8px rgba(179,160,255,.45)", duration: 0.2 }, T + 1.22);
    NX.burst(tl, el, T + 1.25, { x: 1240, y: 876, n: 14, r: 170, c: "#b3a0ff", c2: "#71cd94" });
    var chip = q("#s11chip"), gbEl = q("#s11gb"), gb = { v: 2 };
    tl.fromTo(chip, { opacity: 0, scale: 0.6, y: 20 }, { opacity: 1, scale: 1, y: 0, duration: 0.45, ease: "back.out(2.2)" }, T + 1.4);
    tl.to(gb, { v: 4, duration: 0.6, ease: "power2.inOut", onUpdate: function () { gbEl.textContent = (gb.v < 3.995 ? "2 GB → " + Math.round(gb.v) : "2 GB → 4") + " GB RAM"; } }, T + 1.55);
    /* hide under the wipe (cut_at 32.85) */
    tl.to([p, chip, q("#s11lbl")], { opacity: 0, duration: 0.01 }, 32.86);
  }
});

