NX.scene({
  id: "s12",
  html: function (c) {
    var E = NX.esc;
    var codeSize = NX.fitSize(c.code, 800, 156, 60, 760, 1);
    var chipW = c.generic ? 1000 : Math.min(1500, Math.max(760, Math.ceil(NX.measure(c.code, NX.fontFor(c.code, 800, codeSize)) + 96 + 34 + 120)));
    var kick = NX.txt(c.generic ? "useMyCode" : "useCode");
    var e1 = NX.txt("end1"), e1Size = NX.fitSize(e1, 700, 70, 40, 1600, 1);
    var chips = [c.gameKey].concat(NX.CHIPS.filter(function (k) { return k !== c.gameKey; })).slice(0, 6);
    var chipImgs = chips.map(function (k) { return '<img class="s12g" src="' + NX.GAMES[k].cover + '" alt="" style="width:56px;height:84px;object-fit:cover;border-radius:10px;flex:none"/>'; }).join("");
    var urlSize = NX.fitSize(c.url, 500, 36, 24, 900, 1, true);
