      '<div style="position:absolute;left:0;right:0;top:340px;height:200px;display:flex;justify-content:center"><div id="s12chip" class="chipcode" style="width:' + chipW + 'px;height:200px;justify-content:center;gap:34px;border-width:5px;box-shadow:0 0 80px rgba(139,92,246,.6),inset 0 0 50px rgba(91,155,255,.2)">' +
