      "</div></div>" +
      '<div id="s12e1" style="position:absolute;left:0;right:0;top:600px;text-align:center;font:700 ' + e1Size + 'px/1.05 Geist;letter-spacing:-.035em">' + NX.hl("end1").replace(/<em>/g, '<em style="font-style:normal;color:var(--nx-soft)">') + "</div>" +
