import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const args = process.argv.slice(2);
const flag = (n) => args.includes("--" + n);
const opt = (n, d) => { const i = args.indexOf("--" + n); return i >= 0 ? args[i + 1] : d; };

const GAMES = ["minecraft", "minecraft-bedrock", "valheim", "rust", "project-zomboid", "palworld", "factorio", "the-forest", "enshrouded", "terraria"];
const LANGS = ["en", "es", "tr", "hi", "tl"];
const LANG_ALIASES = { english: "en", spanish: "es", espanol: "es", turkish: "tr", hindi: "hi", tagalog: "tl", filipino: "tl" };
const OPTIONAL = ["handle", "discountFirst", "discountAfter", "priceBefore", "priceAfter", "renewPrice", "upgradePrice", "upgradeRenew", "tier8Price"];

function parseCSV(text) {
  const rows = [];
  for (const line of text.split(/\r?\n/)) {
    if (!line.trim() || line.trim().startsWith("#")) continue;
    const cells = []; let cur = "", q = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') { if (q && line[i + 1] === '"') { cur += '"'; i++; } else q = !q; }
      else if (ch === "," && !q) { cells.push(cur); cur = ""; }
      else cur += ch;
    }
    cells.push(cur);
    rows.push(cells.map((c) => c.trim()));
  }
  const [head, ...body] = rows;
  return body.map((r) => Object.fromEntries(head.map((h, i) => [h, r[i] ?? ""])));
}
const norm = (s) => String(s || "").toLowerCase().replace(/creators?/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
function gameKey(s) {
  const n = norm(s);
  if (GAMES.includes(n)) return n;
  if (n === "zomboid") return "project-zomboid";
  if (n === "forest") return "the-forest";
  if (n.includes("bedrock")) return "minecraft-bedrock";
  return null;
}
function langList(s) {
  const out = String(s || "en").split(/[;|/&]+|\band\b/i).map((x) => x.trim().toLowerCase()).filter(Boolean)
    .map((x) => LANG_ALIASES[x.replace(/ version$/, "")] || x.slice(0, 2));
  return [...new Set(out.filter((x) => LANGS.includes(x)))];
}

const csv = parseCSV(readFileSync(join(ROOT, "creators.csv"), "utf8"));
const only = opt("only") ? opt("only").toUpperCase().split(",") : null;
const onlyLang = opt("lang");
const format = opt("format", "both");
const draft = flag("draft");
const formats = format === "both" ? ["16x9", "9x16"] : [format];
const hasVertical = existsSync(join(ROOT, "index-vertical.html"));

const jobs = [];
for (const r of csv) {
  const code = String(r.code || "").toUpperCase().replace(/[^A-Z0-9_-]/g, "");
  if (!code) continue;
  if (only && !only.includes(code)) continue;
  let game = gameKey(r.game);
  if (!game) { console.warn(`! ${code}: game "${r.game}" has no art yet; using minecraft`); game = "minecraft"; }
  const vars = { code, game, url: String(r.url || "").replace(/^https?:\/\//, "") };
  for (const k of OPTIONAL) if (r[k]) vars[k === "handle" ? "creatorHandle" : k] = /^discount/.test(k) ? Number(r[k]) : r[k];
  for (const lang of langList(r.languages)) {
    if (onlyLang && lang !== onlyLang) continue;
    for (const f of formats) jobs.push({ code, lang, f, vars: { ...vars, lang } });
  }
}
if (flag("generic")) for (const lang of onlyLang ? [onlyLang] : ["en"]) for (const f of formats) jobs.push({ code: "GENERIC", lang, f, vars: { generic: true, lang } });

console.log(`${jobs.length} render(s)${draft ? " (draft)" : ""}:`);
for (const j of jobs) console.log(`  ${j.code.padEnd(10)} ${j.lang}  ${j.f}  game=${j.vars.game || "-"}`);
if (flag("list")) process.exit(0);

mkdirSync(join(ROOT, "renders", "creators"), { recursive: true });
const tmp = join(ROOT, ".hyperframes", "batch"); mkdirSync(tmp, { recursive: true });
const failures = [];
for (const [i, j] of jobs.entries()) {
  if (j.f === "9x16" && !hasVertical) { console.warn(`- skip ${j.code} ${j.lang} 9x16 (index-vertical.html not built yet)`); continue; }
  const dir = join(ROOT, "renders", "creators", j.code); mkdirSync(dir, { recursive: true });
  const out = join(dir, `nxeon-promo_${j.code}_${j.lang}_${j.f}${draft ? "_draft" : ""}.mp4`);
  const vf = join(tmp, `${j.code}_${j.lang}_${j.f}.json`); writeFileSync(vf, JSON.stringify(j.vars, null, 2));
  const cli = ["hyperframes", "render", "--quiet", "--strict-variables", "--variables-file", vf, "-o", out,
    "-f", draft ? "30" : "60", "-q", draft ? "draft" : "high"];
  if (j.f === "9x16") cli.push("--composition", "index-vertical.html");
  console.log(`\n[${i + 1}/${jobs.length}] ${j.code} ${j.lang} ${j.f} → ${out}`);
  const t0 = Date.now();
  const res = spawnSync("npx", cli, { cwd: ROOT, stdio: "inherit", shell: process.platform === "win32" });
  if (res.status !== 0) failures.push(`${j.code} ${j.lang} ${j.f}`);
  else console.log(`  done in ${((Date.now() - t0) / 1000).toFixed(0)}s`);
}
if (failures.length) { console.error(`\n${failures.length} failed:\n  ` + failures.join("\n  ")); process.exit(1); }
console.log("\nAll renders finished. Output: renders/creators/<CODE>/");

