/* Entry: a non-click first point is only an approach hint. The cursor glides in ONE decelerating
   tween from beyond it straight onto the first target, arriving just before the click.
   Later moves never start before the previous one ends, so x/y tweens never overlap. */
var first = pts[0];
var target = (first.click || pts.length < 2) ? first : pts[1];
var dx = first.x - target.x, dy = first.y - target.y;
if (target === first) { dx = o.enterDx || 260; dy = o.enterDy || 180; }
var len = Math.hypot(dx, dy) || 1, k = (len + 140) / len;
var arrive = target === first ? first.t + 0.45 : target.t - 0.03;
tl.fromTo(cur, { x: target.x + dx * k, y: target.y + dy * k },
  { x: target.x, y: target.y, duration: arrive - first.t, ease: "power3.out", immediateRender: false }, first.t);
tl.fromTo(cur, { opacity: 0 }, { opacity: 1, duration: 0.18, immediateRender: false }, first.t);
var prevEnd = arrive, prev = target;
for (var i = pts.indexOf(target) + 1; i < pts.length; i++) {
  var b = pts[i];
  if (b.x === prev.x && b.y === prev.y) continue;
  var start = Math.max(prevEnd + (prev.click ? 0.12 : 0), b.t - 0.55);
  var dur = Math.max(0.2, b.t - 0.03 - start);
  tl.to(cur, { x: b.x, y: b.y, duration: dur, ease: "power2.inOut" }, start);
  prevEnd = start + dur; prev = b;
}

