/* 01 · Logo sting (0–2.5 s). NX mark slams, wordmark wipes on, tagline, over the NX-cloud wallpaper.
   Overlay mode (c.overlay): no wallpaper, scrim or flash; it fades out so the last frame is transparent. */
NX.scene({
  id: "s01",
  html: function (c) {
    var V = NX.orient === "v", W = V ? 1080 : 1920, H = V ? 1920 : 1080;
    /* lockup geometry: the PNG is 1197×208, mark = left 417px of it */
    var lw = V ? 900 : 1100, lh = Math.round(lw * 208 / 1197), mw = Math.round(lw * 417 / 1197);
    var lx = Math.round((W - lw) / 2), ly = V ? 722 : 374;
    var ring = V ? 400 : 480, rcx = lx + mw / 2, rcy = ly + lh / 2;
    var tag = NX.txt("tagline");
    var size = V ? NX.fitSize(tag, 600, 64, 36, 960, 2) : NX.fitSize(tag, 600, 62, 36, 1600, 1);
    var tagTop = V ? 930 : 650;
    var bg = c.overlay ? "" :
      '<img id="s01wall" src="assets/brand/wallpaper.png" alt="" style="position:absolute;inset:0;width:' + W + "px;height:" + H + 'px;object-fit:cover;filter:brightness(.34) saturate(1.1) blur(2px)"/>' +
      '<div style="position:absolute;inset:0;background:radial-gradient(' + (V ? "700px 900px" : "900px 520px") + ' at 50% 46%,rgba(4,8,23,.45),rgba(4,8,23,.9) 75%)"></div>';
    NX._s01 = { mw: mw };
    return '' +
      '<div id="s01in" style="position:absolute;inset:0">' + bg +
        '<div id="s01ring" style="position:absolute;left:' + Math.round(rcx - ring / 2) + "px;top:" + Math.round(rcy - ring / 2) + "px;width:" + ring + "px;height:" + ring + 'px;border-radius:50%;border:3px solid rgba(91,155,255,.7);box-shadow:0 0 60px rgba(91,155,255,.45),inset 0 0 40px rgba(91,155,255,.25)"></div>' +
        '<div id="s01logo" style="position:absolute;left:' + lx + "px;top:" + ly + "px;width:" + lw + "px;height:" + lh + 'px">' +
          '<img id="s01word" src="assets/brand/logo-lockup.png" alt="NXEON" style="position:absolute;left:0;top:0;width:' + lw + "px;height:" + lh + "px;clip-path:inset(0 0 0 " + mw + 'px)"/>' +
          '<img id="s01mark" src="assets/brand/nx-mark.png" alt="" style="position:absolute;left:0;top:0;width:' + mw + "px;height:" + lh + 'px"/>' +
        "</div>" +
        '<div id="s01tag" style="position:absolute;left:' + (V ? 60 : 0) + "px;right:" + (V ? 60 : 0) + "px;top:" + tagTop + "px;text-align:center;font-weight:600;font-size:" + size + 'px;line-height:1.15;letter-spacing:-.03em">' + NX.words("tagline") + "</div>" +
        (c.overlay ? "" : '<div id="s01flash" style="position:absolute;inset:0;background:#dfe6ff;opacity:0"></div>') +
      "</div>";
  },
  build: function (tl, c, el) {
    var q = function (s) { return el.querySelector(s); }, mw = NX._s01.mw;
    if (q("#s01wall")) tl.fromTo(q("#s01wall"), { scale: 1.0 }, { scale: 1.08, duration: 2.4, ease: "none" }, 0);
    tl.fromTo(q("#s01mark"), { scale: 1.75, opacity: 0, filter: "blur(18px)", transformOrigin: "50% 50%" },
      { scale: 1, opacity: 1, filter: "blur(0px)", duration: 0.38, ease: "expo.out" }, 0.08);
    tl.fromTo(q("#s01ring"), { scale: 0.45, opacity: 0 }, { scale: 1.3, duration: 0.7, ease: "expo.out" }, 0.4);
    tl.fromTo(q("#s01ring"), { opacity: 0 }, { opacity: 1, duration: 0.06 }, 0.4);
    tl.to(q("#s01ring"), { opacity: 0, duration: 0.5, ease: "power2.out" }, 0.62);
    if (q("#s01flash")) {
      tl.fromTo(q("#s01flash"), { opacity: 0 }, { opacity: 0.22, duration: 0.05 }, 0.42);
      tl.to(q("#s01flash"), { opacity: 0, duration: 0.25, ease: "power2.out" }, 0.47);
    }
    tl.fromTo(q("#s01word"), { clipPath: "inset(0px 100% 0px " + mw + "px)", x: -24 }, { clipPath: "inset(0px 0% 0px " + mw + "px)", x: 0, duration: 0.55, ease: "expo.out" }, 0.55);
    tl.fromTo(q("#s01tag").querySelectorAll(".w"), { yPercent: 110 }, { yPercent: 0, duration: 0.6, ease: "expo.out", stagger: 0.07 }, 0.95);
    tl.fromTo(q("#s01logo"), { scale: 1 }, { scale: 1.035, duration: 1.9, ease: "none" }, 0.5);
    if (c.overlay) tl.to(q("#s01in"), { opacity: 0, duration: 0.3, ease: "power2.in" }, 2.15);
    else tl.to(q("#s01in"), { opacity: 0, duration: 0.01 }, 2.36);
  }
});

