/* 13 · Code lower-third (overlay kit only, 0–6 s, transparent). "USE CODE {CODE}" chip with the −50%
   badge and the partner URL, bottom-left, for creators to place over their own footage. */
NX.scene({
  id: "s13",
  html: function (c) {
    var E = NX.esc;
    var codeSize = NX.fitSize(c.code, 800, 72, 36, 520, 1);
    var codeW = Math.ceil(NX.measure(c.code, NX.fontFor(c.code, 800, codeSize)));
    var kick = NX.txt("useCode"), kickW = Math.ceil(NX.measure(kick, NX.fontFor(kick, 500, 20, true)) * 1.35);
    var chipW = 30 + 56 + 24 + Math.max(codeW, kickW) + 120;
    var urlSize = NX.fitSize(c.url, 500, 28, 18, 640, 1, true);
    return '' +
      '<div id="s13box" style="position:absolute;left:96px;top:772px">' +
        '<div id="s13chip" class="chipcode" style="position:relative;width:' + chipW + 'px;height:124px;gap:24px;padding:0 40px 0 30px">' +
          NX.icon("tag", "width:56px;height:56px;color:#b3a0ff") +
          '<div style="display:flex;flex-direction:column;gap:6px"><span class="mono" style="font-size:20px;letter-spacing:.3em;color:var(--mist);white-space:nowrap">' + E(kick) + '</span>' +
          '<span id="s13code" style="font:800 ' + codeSize + 'px/1 Geist;letter-spacing:-.02em;white-space:nowrap"></span></div>' +
        "</div>" +
        '<div id="s13badge" style="position:absolute;left:' + (chipW - 56) + 'px;top:-46px;width:132px;height:132px;clip-path:polygon(50% 0,61% 12%,76% 6%,80% 21%,96% 24%,91% 39%,100% 50%,91% 61%,96% 76%,80% 79%,76% 94%,61% 88%,50% 100%,39% 88%,24% 94%,20% 79%,4% 76%,9% 61%,0 50%,9% 39%,4% 24%,20% 21%,24% 6%,39% 12%);background:radial-gradient(circle at 40% 35%,#a98bff,#6b3bdb 70%);display:grid;place-items:center">' +
          '<span style="font:800 38px/1 Geist;color:#fff;letter-spacing:-.03em">−' + E(c.d1) + "%</span></div>" +
        '<div id="s13url" class="mono" style="position:absolute;left:8px;top:142px;display:flex;align-items:center;height:56px;padding:0 26px;border-radius:999px;border:2px solid var(--ui-border-strong);background:rgba(10,16,48,.9);font-size:' + urlSize + 'px;color:var(--ink);white-space:nowrap">' + E(c.url) + "</div>" +
      "</div>";
  },
  build: function (tl, c, el) {
    var T = NX.T.s13[0], D = NX.T.s13[1] - T, q = function (s) { return el.querySelector(s); };
    var chip = q("#s13chip"), badge = q("#s13badge"), url = q("#s13url");
    tl.fromTo(chip, { opacity: 0, x: -140 }, { opacity: 1, x: 0, duration: 0.6, ease: "expo.out" }, T + 0.15);
    NX.typeText(tl, q("#s13code"), c.code, T + 0.4, Math.min(0.6, 0.06 * c.code.length + 0.1));
    tl.fromTo(badge, { opacity: 0, scale: 0, rotation: -50 }, { opacity: 1, scale: 1, rotation: -12, duration: 0.55, ease: "back.out(2.2)" }, T + 0.95);
    tl.fromTo(url, { opacity: 0, y: -12 }, { opacity: 1, y: 0, duration: 0.45, ease: "power3.out" }, T + 1.15);
    tl.to(chip, { boxShadow: "0 0 90px rgba(139,92,246,.85),inset 0 0 50px rgba(91,155,255,.3)", duration: 0.6, ease: "sine.inOut", yoyo: true, repeat: 3 }, T + 1.8);
    /* exit: everything leaves left; last frame fully transparent */
    tl.to([chip, badge, url], { opacity: 0, x: -120, duration: 0.4, ease: "power2.in", stagger: 0.05 }, T + D - 0.7);
  }
});

