/* Overlay kit builder: mounts ONE scene on a transparent root and remaps its timeline so the
   overlay starts at 0. Used by compositions/overlay-*.html (rendered as ProRes 4444 with alpha). */
(function () {
  var NX = window.NX;
  NX.T.s13 = [0, 6];
  var KINDS = {
    sting: { scene: "s01", from: 0, to: 2.5 },
    code: { scene: "s13", from: 0, to: 6 },
    endcard: { scene: "s12", from: NX.T.s12[0], to: NX.T.s12[1] }
  };
  NX.buildOverlay = function (kind) {
    var k = KINDS[kind], ctx = NX.ctx = NX.vars();
    ctx.overlay = kind;
    NX.S = NX.STRINGS[ctx.lang];
    var root = document.getElementById("root");
    root.classList.add("lang-" + ctx.lang);
    var scene = NX.scenes.filter(function (s) { return s.id === k.scene; })[0];
    var el = document.getElementById(k.scene);
    el.innerHTML = scene.html(ctx);
    var master = gsap.timeline({ paused: true });
    scene.build(master, ctx, el);
    if (k.from === 0) return master;
    var tl = gsap.timeline({ paused: true });
    tl.add(master.tweenFromTo(k.from, k.to, { duration: k.to - k.from, ease: "none" }), 0);
    return tl;
  };
})();

