#!/usr/bin/env node
/* Transparent overlay kit (ProRes 4444 .mov with alpha, 1920×1080 @ 60 fps).
   Creators drop these over their own footage: logo sting (2.5 s), code lower-third (6 s), end card (6.5 s).

   node tools/render-overlays.mjs                     # generic kit (placeholder code YOURCODE) → renders/overlays/
   node tools/render-overlays.mjs --only HOVEN        # kit with that creator's code/language from creators.csv
   node tools/render-overlays.mjs --kinds code,endcard
   Each file starts and ends fully transparent. The end card carries a dark scrim for legibility. */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
