### Step 6: the render worker (separate process)

`worker-render/index.ts`, started by its own service. Mirrors `worker/index.ts`'s loop and atomic claim; imports `db` from `../lib/db`.

```ts
import { spawn } from "node:child_process";
import { mkdir, writeFile, rm, rename, stat, readdir } from "node:fs/promises";
import { join } from "node:path";
import { db } from "../lib/db";
import { howToUse } from "../lib/promo-howto";

const TPL = process.env.PROMO_TEMPLATE_DIR ?? "/opt/nxeon/video-templates/creator-promo";
const ROOT = process.env.PROMO_RENDER_DIR ?? "/var/lib/nxeon/promo-renders";
const HF = "hyperframes@0.8.140";
const POLL_MS = 5000, TIMEOUT_MS = Number(process.env.PROMO_TIMEOUT_MS ?? 30 * 60_000);
const RETENTION_DAYS = Number(process.env.PROMO_RETENTION_DAYS ?? 14);

function run(cmd: string, args: string[], cwd: string): Promise<void> {            // NO shell, args array only
  return new Promise((resolve, reject) => {
    const p = spawn(cmd, args, { cwd, stdio: ["ignore", "pipe", "pipe"] });
    let tail = ""; const keep = (b: Buffer) => { tail = (tail + b.toString()).slice(-4000); };
    p.stdout.on("data", keep); p.stderr.on("data", keep);
    const t = setTimeout(() => p.kill("SIGKILL"), TIMEOUT_MS);
    p.on("error", reject);
    p.on("close", (c) => { clearTimeout(t); c === 0 ? resolve() : reject(new Error(`${cmd} exited ${c}: ${tail.slice(-600)}`)); });
  });
}
const hf = (vf: string, out: string, extra: string[]) =>
  ["--yes", HF, "render", "--quiet", "--strict-variables", "--variables-file", vf, "-w", process.env.PROMO_WORKERS ?? "2", "-o", out, ...extra];

async function render(r: { id: string; partnerId: string; vars: any; formats: string }) {
  const code: string = r.vars.code, lang: string = r.vars.lang;
  const rel = `${r.partnerId}/${r.id}`, tmp = join(ROOT, ".tmp", r.id), final = join(ROOT, rel);
  await rm(tmp, { recursive: true, force: true }); await mkdir(tmp, { recursive: true });
  const vf = join(tmp, "vars.json"); await writeFile(vf, JSON.stringify(r.vars));
  const want = r.formats.split(",");
  const tasks: { label: string; out: string; args: string[] }[] = [];
  if (want.includes("16x9")) tasks.push({ label: "16:9 video", out: `nxeon-promo_${code}_${lang}_16x9.mp4`, args: ["-f", "60", "-q", "high"] });
  if (want.includes("9x16")) tasks.push({ label: "9:16 video", out: `nxeon-promo_${code}_${lang}_9x16.mp4`, args: ["-f", "60", "-q", "high", "--composition", "compositions/vertical.html"] });
  if (want.includes("overlays")) for (const k of ["sting", "code", "endcard"]) tasks.push({ label: `overlay: ${k}`, out: `nxeon-overlay_${k}_${code}.mov`, args: ["--format", "mov", "-f", "60", "--composition", `compositions/overlay-${k}.html`] });
  const files: { name: string; kind: string; bytes: number }[] = [];
  for (const [i, t] of tasks.entries()) {
    await db.promoRender.update({ where: { id: r.id }, data: { step: `Rendering ${t.label}`, progress: Math.round((i / (tasks.length + 1)) * 100) } });
    await run("npx", hf(vf, join(tmp, t.out), t.args), TPL);
    files.push({ name: t.out, kind: t.out.endsWith(".mov") ? "overlay" : "video", bytes: (await stat(join(tmp, t.out))).size });
    if (t.out.endsWith(".mp4")) {                                                           // end-frame PNG for thumbnails
      const png = t.out.replace(/\.mp4$/, "_endframe.png");
      await run("ffmpeg", ["-v", "error", "-y", "-sseof", "-0.1", "-i", join(tmp, t.out), "-frames:v", "1", join(tmp, png)], tmp);
      files.push({ name: png, kind: "image", bytes: (await stat(join(tmp, png))).size });
    }
  }
  await writeFile(join(tmp, "HOW-TO-USE.txt"), howToUse(r.vars, files.map((f) => f.name)));
  files.push({ name: "HOW-TO-USE.txt", kind: "text", bytes: (await stat(join(tmp, "HOW-TO-USE.txt"))).size });
  await rm(join(tmp, "vars.json"));
  await mkdir(join(ROOT, r.partnerId), { recursive: true }); await rm(final, { recursive: true, force: true }); await rename(tmp, final);
  return { rel, files };
}

async function main() {
  await mkdir(ROOT, { recursive: true });
  await db.promoRender.updateMany({ where: { status: "RUNNING" }, data: { status: "QUEUED" } });   // single worker: anything RUNNING at boot is stale
  let lastSweep = 0;
  for (;;) {
    try {
      if (Date.now() - lastSweep > 3_600_000) { lastSweep = Date.now(); await sweepExpired(); }
      const c = await db.promoRender.findFirst({ where: { status: "QUEUED" }, orderBy: { createdAt: "asc" } });
      if (!c) { await new Promise((r) => setTimeout(r, POLL_MS)); continue; }
      const claim = await db.promoRender.updateMany({ where: { id: c.id, status: "QUEUED" }, data: { status: "RUNNING", attempts: { increment: 1 }, startedAt: new Date(), error: null } });
      if (claim.count !== 1) continue;
      try {
        const { rel, files } = await render(c as any);
        await db.promoRender.update({ where: { id: c.id }, data: { status: "DONE", progress: 100, step: "Done", outputDir: rel, files, finishedAt: new Date() } });
      } catch (e: any) {
        const retry = c.attempts + 1 < 2;
        await db.promoRender.update({ where: { id: c.id }, data: { status: retry ? "QUEUED" : "FAILED", error: String(e?.message ?? e).slice(0, 1500), step: null } });
      }
    } catch (e) { console.error("[render-worker]", e); await new Promise((r) => setTimeout(r, POLL_MS)); }
  }
}
async function sweepExpired() {          // delete files of DONE renders older than RETENTION_DAYS, keep the row as EXPIRED
  const old = await db.promoRender.findMany({ where: { status: "DONE", finishedAt: { lt: new Date(Date.now() - RETENTION_DAYS * 86_400_000) } } });
  for (const r of old) { if (r.outputDir) await rm(join(ROOT, r.outputDir), { recursive: true, force: true }); await db.promoRender.update({ where: { id: r.id }, data: { status: "EXPIRED", files: null } }); }
}
main();
```

